insert into curriculum_topics values ('N3-basic-science-and-technology-t2-w9','ng-scheme-2025-preprimary-primary','N3','basic-science-and-technology',2,'9',9,'teaching',null,'Water and Transportation','["Water:", "Importance of water: drinking, cooking, bathing, washing, plants need it, animals need it", "Sources of water: rain, rivers, streams, wells, boreholes, taps", "Understanding clean vs dirty water Transportation:", "Definition of transportation: moving people and things from one place to another", "Means of transportation: land (cars, buses, bicycles, motorcycles, trains), water (boats, ships, canoes), air (airplanes, helicopters)", "Importance of transportation: going to school, work, market, hospital; moving goods", "Safety in transportation: seatbelts, life jackets, following traffic rules"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,495) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-basic-science-and-technology-t2-w10','ng-scheme-2025-preprimary-primary','N3','basic-science-and-technology',2,'10',10,'teaching',null,'Bones','["Bones:", "Understanding bones: hard structures inside our body (skeleton)", "Functions of bones: give body shape, support body, protect organs (skull protects brain, ribs protect heart and lungs), help us move (with muscles)", "Major bones: skull (head), spine (back), ribs (chest), arm bones, leg bones", "Keeping bones strong: drinking milk, eating calcium-rich foods, exercising, playing"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,496) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-basic-science-and-technology-t2-w11','ng-scheme-2025-preprimary-primary','N3','basic-science-and-technology',2,'11',11,'teaching',null,'Technology','["Technology", "Mobile Phones:", "Understanding technology: tools that make life easier", "Mobile phones: devices for talking to people far away", "Uses: calling, sending messages, taking pictures, learning, emergencies", "Phone safety: ask adults before using, not a toy, careful handling"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,496) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-basic-science-and-technology-t2-w12','ng-scheme-2025-preprimary-primary','N3','basic-science-and-technology',2,'12',12,'examination',null,'End of Term Examination','["Rocks and soil comprehensive test", "Food knowledge assessment", "Living things and characteristics test", "Growth in animals and plants evaluation", "Water and transportation test", "Bones and technology assessment", "Overall science knowledge evaluation"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,496) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-basic-science-and-technology-t2-w13','ng-scheme-2025-preprimary-primary','N3','basic-science-and-technology',2,'13',13,'closing',null,'Closing & End of Term Activities','["Return of examination scripts", "Distribution of report cards", "Science achievements celebration", "Awards for scientific curiosity", "Holiday science observation tips", "Preview of third term topics"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,496) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-basic-science-and-technology-t3-w1','ng-scheme-2025-preprimary-primary','N3','basic-science-and-technology',3,'1',1,'teaching',null,'Water: Methods of Purification','["Understanding water purification: making dirty water clean and safe to drink", "Why purify water: remove dirt, kill germs, prevent diseases", "Methods of water purification: *Boiling: heating water until it bubbles, kills germs (most common method at home) * Filtration: passing water through filter to remove dirt *Adding chemicals: water purification tablets, chlorine (in treated water) *Settling and decanting: letting dirt settle, pouring clean water off top", "Importance of drinking clean water only", "Understanding tap water is usually treated"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,496) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-basic-science-and-technology-t3-w2','ng-scheme-2025-preprimary-primary','N3','basic-science-and-technology',3,'2',2,'teaching',null,'Water: Storage','["Importance of proper water storage: keeps water clean, prevents contamination", "Safe water storage containers: covered buckets, jerry cans, water tanks, bottles", "Properties of good storage containers: clean, covered (to keep out dirt and insects), made of safe materials", "Storage practices: washing containers before use, keeping containers covered always, storing in clean place, not touching water with dirty hands", "Understanding stored water can become dirty if not protected", "Regular cleaning of storage containers"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,497) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-basic-science-and-technology-t3-w3','ng-scheme-2025-preprimary-primary','N3','basic-science-and-technology',3,'3',3,'teaching',null,'Water-borne Diseases','["Understanding water-borne diseases: sicknesses caused by dirty water or germs in water", "Common water-borne diseases: diarrhea, cholera, typhoid fever, dysentery", "How diseases spread through water: drinking dirty water, eating food washed with dirty water, not washing hands", "Symptoms: stomach pain, vomiting, diarrhea (frequent watery stool), weakness, fever", "Prevention: drinking only clean/boiled water, washing hands with soap, keeping water covered, proper toilet use", "Treatment: see doctor immediately, drink plenty of clean water (ORS", "Oral Rehydration Solution)", "Understanding prevention is better than cure"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,497) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-basic-science-and-technology-t3-w4','ng-scheme-2025-preprimary-primary','N3','basic-science-and-technology',3,'4',4,'teaching',null,'Technology: Security Gadgets','["Understanding security: keeping people and property safe", "Security gadgets: tools that help protect us", "Types of security gadgets: * Locks and keys: secure doors and gates *Burglar alarms: make loud sound when intruder enters * CCTV cameras: record what happens, help catch thieves *Security lights: bright lights that come on at night * Smoke alarms: warn of fire", "Importance of security gadgets: protect homes, schools, shops from thieves; keep us safe", "Understanding to call adults if alarm sounds", "Security personnel and their gadgets"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,498) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-basic-science-and-technology-t3-w5','ng-scheme-2025-preprimary-primary','N3','basic-science-and-technology',3,'5',5,'midterm_assessment',null,'Mid-term Assessment/test','["Water purification methods test", "Water storage practices assessment", "Water-borne diseases knowledge test", "Security gadgets identification and uses", "Safety and health awareness evaluation", "Practical knowledge assessment"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,498) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-basic-science-and-technology-t3-w6','ng-scheme-2025-preprimary-primary','N3','basic-science-and-technology',3,'6',6,'midterm_break',null,'Mid-term Break','[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,498) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-basic-science-and-technology-t3-w7','ng-scheme-2025-preprimary-primary','N3','basic-science-and-technology',3,'7',7,'teaching',null,'Animals and Their Homes','["Understanding animals live in different places (habitats/homes)", "Animal homes and their names: * Dog → kennel * Cat → cattery/house * Bird → nest * Bee → hive * Lion → den * Rabbit → burrow/warren * Fish → water/aquarium * Cow → barn/shed * Chicken → coop * Spider → web * Ant → anthill * Horse → stable", "Wild animal homes: forests, caves, trees, underground", "Domestic animal homes: made by humans", "Understanding animals choose/build homes for shelter and safety"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,498) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-basic-science-and-technology-t3-w8','ng-scheme-2025-preprimary-primary','N3','basic-science-and-technology',3,'8',8,'teaching',null,'Animals and Their Young Ones','["Understanding animals have babies/young ones", "Animal babies and their names: * Dog → puppy * Cat → kitten * Cow → calf * Horse → foal * Sheep → lamb * Goat → kid * Chicken → chick * Duck → duckling * Frog → tadpole * Butterfly → caterpillar * Lion → cub * Elephant → calf * Bear → cub", "Understanding baby animals look like parents (but some go through changes like frog)", "Parent animals care for their young: feed, protect, teach", "Matching animals to their young ones"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,499) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-basic-science-and-technology-t3-w9','ng-scheme-2025-preprimary-primary','N3','basic-science-and-technology',3,'9',9,'teaching',null,'Technology: Simple Machines Used in the Home','["Understanding machines: tools that make work easier", "Simple machines used at home: * Broom → sweeping floors * Knife → cutting food * Scissors → cutting paper, cloth * Spoon and fork → eating * Bottle opener → opening bottles * Can opener → opening cans * Hammer → hitting nails * Screwdriver → tightening screws * Iron → pressing clothes * Fan → cooling air", "How machines help: make work faster, easier, and better", "Safety: some machines only for adults, be careful with sharp objects", "Proper use and care of home machines"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,499) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-basic-science-and-technology-t3-w10','ng-scheme-2025-preprimary-primary','N3','basic-science-and-technology',3,'10',10,'teaching',null,'Technology: Simple Machines Used in School','["Simple machines used at school: * Pencil sharpener → sharpening pencils * Scissors → cutting paper for art * Stapler → joining papers together * Hole puncher → making holes in paper * Ruler → measuring, drawing straight lines * Eraser → removing pencil marks * Bell/gong → signaling time * Dustpan and brush → cleaning classroom *Playground equipment → swings, slides (simple machines - levers, inclined planes)", "How school machines help learning and activities", "Taking care of school equipment", "Sharing machines fairly with classmates", "Proper use and safety"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,499) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-basic-science-and-technology-t3-w11','ng-scheme-2025-preprimary-primary','N3','basic-science-and-technology',3,'11',11,'revision',null,'Revision of Third Term & Year''s Work','["Third Term Review:", "Water purification, storage, and diseases", "Security gadgets", "Animals: homes and young ones", "Technology: machines at home and school Year-Long Comprehensive Review:", "First Term: body, body care, first aid, wounds, sickness, rocks, soil", "Second Term: food, living things, growth, water, bones, technology", "Third Term: all topics covered", "Mock examination exercises", "Practical science observations", "Comprehensive review activities"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,500) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-basic-science-and-technology-t3-w12','ng-scheme-2025-preprimary-primary','N3','basic-science-and-technology',3,'12',12,'examination',null,'End of Year Examination','["Third Term Assessment:", "Water knowledge comprehensive test", "Security gadgets test", "Animals and young ones assessment", "Simple machines identification and uses Comprehensive Year Assessment:", "Body and health knowledge", "Food and living things", "Growth and development", "Water, rocks, and soil", "Technology and machines", "Animals knowledge", "Overall Nursery 3 science mastery", "Practical science awareness", "Safety consciousness evaluation"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,500) on conflict (id) do nothing;
