insert into curriculum_topics values ('N3-health-habits-t1-w1','ng-scheme-2025-preprimary-primary','N3','health-habits',1,'1',1,'teaching',null,'Exercise: Meaning, Types and Importance','["Meaning of exercise: physical activities that make our body move and work", "Types of exercise: running, jumping, skipping, dancing, swimming, playing football, riding bicycle, walking, stretching, sit-ups, push-ups", "Indoor exercises: stretching, yoga for children, dancing in room", "Outdoor exercises: running, playing, sports", "Importance of exercise: makes body strong, keeps us healthy, helps us grow, makes heart and lungs strong, gives energy, helps us sleep better, makes us happy, prevents obesity", "Understanding exercise should be fun"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,502) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-health-habits-t1-w2','ng-scheme-2025-preprimary-primary','N3','health-habits',1,'2',2,'teaching',null,'Exercise: Where to Exercise and Importance','["Places where we can exercise: home (yard, room), school (playground, field, PE class), park, sports ground, gym (for older children/adults), beach, safe streets (with adult supervision)", "Choosing safe places for exercise: away from roads, flat surfaces, enough space", "Exercise at different times: morning exercise, break time at school, after school play", "Reinforcing importance of regular exercise: daily exercise is best, at least 30 minutes of play/activity, making exercise a habit", "Exercise safety: warming up, proper shoes, drinking water, stopping if tired or in pain"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,502) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-health-habits-t1-w3','ng-scheme-2025-preprimary-primary','N3','health-habits',1,'3',3,'teaching',null,'Care of the Body: How to Take Care and Importance','["How to take care of the body: bathing/washing daily with soap and water, brushing teeth twice daily (morning and night), washing hands frequently (before eating, after toilet, after playing), combing/brushing hair daily, trimming nails regularly, wearing clean clothes, eating healthy food, drinking clean water, getting enough sleep, exercising regularly", "Importance of body care: prevents diseases, keeps us healthy, makes us look neat and smell good, shows self-respect, makes others comfortable around us, prevents skin infections, maintains good health", "Understanding our body is precious and deserves good care"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,502) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-health-habits-t1-w4','ng-scheme-2025-preprimary-primary','N3','health-habits',1,'4',4,'teaching',null,'Care of the Teeth','["Understanding teeth: used for biting and chewing food, help us speak clearly, give us nice smile", "Types of teeth: milk teeth (baby teeth - will fall out), permanent teeth (adult teeth - stay forever)", "How to care for teeth: brushing twice daily (morning and night), using toothbrush and toothpaste, brushing all surfaces (front, back, top), brushing for at least 2 minutes, rinsing mouth after eating, flossing (with adult help)", "Foods good for teeth: milk, cheese, fruits, vegetables, water", "Foods bad for teeth: too many sweets, candies, sugary drinks, sticky foods", "Visiting dentist regularly", "Consequences of poor dental care: tooth decay, cavities, toothache, bad breath, gum disease"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,503) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-health-habits-t1-w5','ng-scheme-2025-preprimary-primary','N3','health-habits',1,'5',5,'midterm_assessment',null,'Mid-term Assessment/test','["Exercise knowledge test", "Body care practices assessment", "Dental care evaluation", "Importance of hygiene test", "Practical demonstration of good habits", "Oral questions on health topics"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,503) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-health-habits-t1-w6','ng-scheme-2025-preprimary-primary','N3','health-habits',1,'6',6,'midterm_break',null,'Mid-term Break','[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,503) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-health-habits-t1-w7','ng-scheme-2025-preprimary-primary','N3','health-habits',1,'7',7,'teaching',null,'Bedtime (Sleep Time): Meaning and Benefits','["Meaning of sleep: natural rest period when body and mind relax, eyes close, become unaware of surroundings", "Understanding everyone needs sleep", "How much sleep children need: 10-12 hours per night for nursery/primary school children", "Benefits of sleep: body grows during sleep, brain rests and learns better after sleep, gives energy for next day, keeps us healthy, helps us concentrate in school, improves mood and behavior, strengthens immune system (fights sickness), helps body heal when sick or injured", "Signs of not enough sleep: tiredness, crankiness, difficulty learning, yawning, falling asleep in class", "Good bedtime routine: bath, brush teeth, bedtime story, lights off at same time"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,503) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-health-habits-t1-w8','ng-scheme-2025-preprimary-primary','N3','health-habits',1,'8',8,'teaching',null,'Cleanliness: Care of School Uniform','["Importance of clean school uniform: looks neat and smart, shows respect for school, prevents body odor, prevents skin infections, makes good impression", "How to care for school uniform: washing after wearing (or at least weekly), drying properly in sun/air, ironing to remove wrinkles, folding or hanging neatly, checking for tears or missing buttons, repairing damage promptly", "Keeping uniform clean during day: not sitting on dirty surfaces, being careful when eating, not playing in mud or dirt while in uniform", "Wearing complete uniform: all required items, proper shoes and socks", "Pride in appearance and representing school well"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,503) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-health-habits-t1-w9','ng-scheme-2025-preprimary-primary','N3','health-habits',1,'9',9,'teaching',null,'Good Eating Habits','["Understanding good eating habits lead to good health", "Good eating habits: washing hands before eating, eating three main meals daily (breakfast, lunch, dinner), eating variety of foods (balanced diet), eating fruits and vegetables daily, drinking plenty of water, chewing food properly, eating slowly, sitting properly while eating, not talking with mouth full, eating right portions (not too much, not too little), eating at regular times, having healthy snacks (fruits, nuts, not just sweets)", "Saying prayers before and after meals (gratitude)", "Not wasting food", "Trying new healthy foods"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,504) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-health-habits-t1-w10','ng-scheme-2025-preprimary-primary','N3','health-habits',1,'10',10,'teaching',null,'Bad Eating Habits','["Understanding bad eating habits harm our health", "Bad eating habits: skipping meals (especially breakfast), eating too much junk food (chips, sweets, soft drinks), eating too fast, eating while playing or watching TV (not paying attention), not chewing properly, talking with mouth full, eating only one type of food, drinking too little water, eating too many sweets and sugary foods, eating dirty or unwashed food, eating with dirty hands, overeating", "Consequences of bad eating habits: tooth decay, obesity (being overweight), malnutrition (not enough nutrients), stomach problems, poor growth, lack of energy, sickness", "How to change bad habits: making conscious effort, parents'' help, choosing healthy alternatives"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,504) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-health-habits-t1-w11','ng-scheme-2025-preprimary-primary','N3','health-habits',1,'11',11,'revision',null,'Revision of First Term Work','["Exercise comprehensive review", "Body care practices revision", "Dental care review", "Sleep importance and bedtime routine", "Uniform care and cleanliness", "Good vs bad eating habits review", "Importance of all health habits", "Mock examination exercises"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,504) on conflict (id) do nothing;
