insert into curriculum_topics values ('N3-health-habits-t2-w1','ng-scheme-2025-preprimary-primary','N3','health-habits',2,'1',1,'teaching',null,'Disposal of Refuse: Safe and Unsafe Ways','["Understanding refuse: waste materials we throw away, garbage, rubbish", "Safe/clean ways of disposing refuse: using waste bins/trash cans, putting refuse in designated places, tying refuse in bags before disposal, taking refuse to collection points, burning in safe incinerators (adults only), burying biodegradable waste in proper pits", "Unsafe/dirty ways: throwing refuse anywhere (littering), dumping in drains/gutters (causes blockage and flooding), throwing in rivers/streams (pollutes water), leaving refuse uncovered (attracts flies, rats, mosquitoes), burning in open areas (air pollution, fire hazard)", "Consequences of improper disposal: diseases, bad smell, dirty environment, blocked drains, flooding", "Everyone''s responsibility to dispose refuse properly"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,506) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-health-habits-t2-w2','ng-scheme-2025-preprimary-primary','N3','health-habits',2,'2',2,'teaching',null,'Disposal of Waste: Meaning and Types','["Meaning of waste: unwanted or unusable materials, things we no longer need", "Understanding waste comes from homes, schools, markets, industries", "Types of waste: Solid waste - paper, cardboard, cartons, plastic bottles, cans, food scraps, leaves, wood, broken items, cloth; Liquid waste - urine, dirty water from washing, drainage water, waste oil, chemical liquids", "Other waste types: biodegradable (can rot/decompose - food, leaves, paper) and non-biodegradable (cannot rot - plastic, glass, metal)", "Proper disposal for each type", "Reducing waste: using less, reusing items, not wasting"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,506) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-health-habits-t2-w3','ng-scheme-2025-preprimary-primary','N3','health-habits',2,'3',3,'teaching',null,'Disposal of Animal Waste','["Understanding animal waste: droppings/feces from animals, dead animals", "Types of animal waste: cow dung, chicken droppings, goat/sheep droppings, dog/cat waste, pig waste", "Proper disposal methods: burying animal waste in pits away from water sources, using for compost/fertilizer (with proper treatment), designated areas for animal waste, washing hands after handling", "Uses of animals: food (meat, milk, eggs), work (farming, transportation), companionship (pets), clothing (leather, wool)", "Uses of animal waste: fertilizer for farms/gardens (manure), biogas production (fuel), compost for plants", "Importance of proper disposal: prevents diseases, reduces bad smell, protects environment, prevents water pollution"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,506) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-health-habits-t2-w4','ng-scheme-2025-preprimary-primary','N3','health-habits',2,'4',4,'teaching',null,'Composting of Waste: Meaning, Benefits and Materials','["Meaning of composting: controlled rotting/decomposing of biodegradable waste to make fertilizer (compost)", "Understanding compost: natural fertilizer made from waste, looks like dark soil", "Benefits of composting: turns waste into useful product, provides nutrients for plants, helps plants grow better, reduces amount of waste, good for environment, saves money (free fertilizer), improves soil quality", "Compost materials: green materials (fresh grass, vegetable scraps, fruit peels, leaves, tea bags), brown materials (dry leaves, paper, cardboard, sawdust, straw), water and air", "What NOT to compost: meat, bones, oils, diseased plants, pet waste", "Simple composting process: pile materials, keep moist, turn regularly, wait (becomes compost after few months)"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,507) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-health-habits-t2-w5','ng-scheme-2025-preprimary-primary','N3','health-habits',2,'5',5,'midterm_assessment',null,'Mid-term Assessment/test','["Refuse disposal methods test", "Types of waste assessment", "Animal waste disposal knowledge", "Composting understanding test", "Environmental health awareness evaluation", "Oral questions on waste management"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,507) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-health-habits-t2-w6','ng-scheme-2025-preprimary-primary','N3','health-habits',2,'6',6,'midterm_break',null,'Mid-term Break','[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,507) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-health-habits-t2-w7','ng-scheme-2025-preprimary-primary','N3','health-habits',2,'7',7,'teaching',null,'Recycling: Definition, Examples and Importance','["Definition of recycling: using waste materials to make new products instead of throwing them away", "Understanding \"Reduce, Reuse, Recycle\" principle", "Examples of objects that can be recycled: Paper - newspapers, cardboard, magazines, books; Plastic -bottles, containers, bags; Glass - bottles, jars; Metal - cans, tins, aluminum foil; Cloth - old clothes, fabric scraps", "Methods of recycling: collecting recyclable materials separately, taking to recycling centers, processing into new products (e.g., plastic bottles → new bottles, clothes, bags; paper → new paper)", "Importance of recycling: saves natural resources, reduces waste in landfills, protects environment, saves energy, creates jobs, reduces pollution, saves money"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,507) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-health-habits-t2-w8','ng-scheme-2025-preprimary-primary','N3','health-habits',2,'8',8,'teaching',null,'Toilet: Types of Toilets','["Understanding toilets: places for urinating and passing feces (waste)", "Traditional toilets: Pit latrine - hole dug in ground with structure over it; Dung-site - open area for waste; Bucket toilet - removable container", "Characteristics: simple, no water needed, common in rural areas, can smell bad, attracts flies", "Modern toilets: Water system (flush toilet) - uses water to flush waste away, connected to sewage or septic tank; Septic tank system - waste goes to underground tank where it decomposes; Soakaway - liquid waste drains into ground through special pit", "Mobile toilet - portable, used at events, construction sites", "Modern toilets: cleaner, less smell, more hygienic", "Importance of using proper toilets (not open defecation)"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,508) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-health-habits-t2-w9','ng-scheme-2025-preprimary-primary','N3','health-habits',2,'9',9,'teaching',null,'Materials for Cleaning Toilets and Importance','["Materials used for cleaning toilets: toilet brush (scrubbing bowl), toilet cleaner/detergent (removes stains and germs), disinfectant (kills germs), water, bucket, mop, broom, dustpan, cleaning cloth/sponge, gloves (protect hands), air freshener", "How to clean toilet: flush first, apply toilet cleaner, scrub with brush, flush again, wipe seat and surfaces, clean floor, dispose dirty water, wash hands thoroughly", "Importance of cleaning toilet: kills germs and bacteria, prevents diseases, removes bad smell, makes toilet pleasant to use, shows respect for others, prevents stains and damage, attracts fewer flies and insects", "Regular cleaning: daily or after use in homes, multiple times daily in schools", "Adults should supervise toilet cleaning for children"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,508) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-health-habits-t2-w10','ng-scheme-2025-preprimary-primary','N3','health-habits',2,'10',10,'teaching',null,'Good and Bad Toilet Habits','["Good toilet habits:", "Flushing after use, using toilet paper properly, washing hands with soap after, keeping toilet clean, not playing in toilet, closing lid when flushing, not littering in toilet, telling adults if toilet is blocked or dirty, using toilet only for intended purpose Bad toilet habits:", "Not flushing after use, not washing hands, throwing paper/objects in toilet bowl (causes blockage), urinating outside toilet bowl, leaving toilet dirty, playing with water in toilet, staying too long in toilet, not closing door for privacy, open defecation (using bush instead of toilet)", "Consequences of bad habits: spreads diseases, bad smell, blocked toilet, disrespect to others, health hazards", "Developing good toilet habits from young age"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,509) on conflict (id) do nothing;
