insert into curriculum_topics values ('N3-health-habits-t3-w1','ng-scheme-2025-preprimary-primary','N3','health-habits',3,'1',1,'teaching',null,'Sanitation: Meaning and Importance','["Meaning of sanitation: keeping our environment clean and free from dirt, germs, and diseases", "Understanding sanitation involves proper disposal of waste, clean water supply, clean toilets, drainage", "Importance of sanitation: prevents diseases, makes environment beautiful, reduces bad smell, prevents breeding of flies and mosquitoes, promotes good health, shows good citizenship, prevents water pollution, makes us feel comfortable and happy", "Personal sanitation vs environmental sanitation", "Everyone''s responsibility to maintain sanitation", "Understanding cleanliness is next to godliness"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,511) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-health-habits-t3-w2','ng-scheme-2025-preprimary-primary','N3','health-habits',3,'2',2,'teaching',null,'Sanitation: Places That Need to Be Sanitised','["Places that need regular sanitation: Home - bedroom, bathroom, toilet, kitchen, living room, compound/yard; School - classrooms, toilets, playground, dining hall, corridors; Public places - markets, bus stops, hospitals, churches/mosques, parks, streets", "How to sanitize different places: sweeping, mopping, washing, disinfecting, proper waste disposal, drainage cleaning", "Frequency of sanitation: daily (toilets, kitchens), weekly (general cleaning), monthly (deep cleaning)", "Community sanitation days", "Understanding clean environment prevents diseases like cholera, typhoid, malaria", "Taking pride in keeping everywhere clean"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,511) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-health-habits-t3-w3','ng-scheme-2025-preprimary-primary','N3','health-habits',3,'3',3,'teaching',null,'Hot Weather: How to Care for Oneself','["Understanding hot weather: when temperature is high, sun is very strong, feels very warm", "What to eat and drink: drink plenty of water (at least 6-8 glasses daily), eat fruits (watermelon, oranges, pineapple - lots of water in them), eat light meals, avoid heavy/fatty foods, drink fresh fruit juice, eat vegetables", "What to wear: light-colored clothes (reflect heat), cotton clothes (allow air), loose clothes, hats or caps (protect head from sun), sunglasses (protect eyes)", "Where to go/activities: stay in shade during hottest hours (12pm-3pm), play in morning or evening, go to cool places, swim (with supervision), stay indoors in afternoon", "Other care: use umbrella or hat when outside, apply sunscreen (for some children), take cool baths, rest when tired, avoid too much running in hot sun"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,511) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-health-habits-t3-w4','ng-scheme-2025-preprimary-primary','N3','health-habits',3,'4',4,'teaching',null,'Cold Weather: How to Care for Oneself','["Understanding cold weather: when temperature is low, feels chilly or very cold, common during harmattan or rainy season", "What to eat and drink: eat warm foods (soup, porridge, hot meals), drink warm drinks (tea, hot chocolate, warm water), eat energy-giving foods (keep body warm), drink enough water (even in cold weather), eat fruits for vitamins (prevent cold/flu)", "What to wear: warm clothes (sweaters, jackets, cardigans), long sleeves and long trousers, socks and covered shoes, scarves (cover neck), caps/hats (cover head and ears), layering clothes (wearing multiple layers)", "Where to go/activities: stay indoors when very cold, close windows at night, use blankets when sleeping, play during warmer parts of day, exercise to keep warm", "Other care: protect from cold wind, dry body properly after bathing, avoid staying wet, seek warmth if shivering"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,512) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-health-habits-t3-w5','ng-scheme-2025-preprimary-primary','N3','health-habits',3,'5',5,'midterm_assessment',null,'Mid-term Assessment/test','["Sanitation knowledge comprehensive test", "Hot weather care assessment", "Cold weather care evaluation", "Health awareness in different conditions", "Practical knowledge of caring for self", "Oral questions on health topics"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,512) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-health-habits-t3-w6','ng-scheme-2025-preprimary-primary','N3','health-habits',3,'6',6,'midterm_break',null,'Mid-term Break','[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,512) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-health-habits-t3-w7','ng-scheme-2025-preprimary-primary','N3','health-habits',3,'7',7,'teaching',null,'Hand Washing: Benefits of Washing Hands Regularly','["Understanding hand washing: cleaning hands with soap and water", "When to wash hands: before eating/cooking, after using toilet, after playing outside, after touching animals, after coughing/sneezing into hands, when hands look dirty, before and after treating wounds", "How to wash hands properly: wet hands with clean water, apply soap, rub hands together (palms, back of hands, between fingers, under nails, wrists) for at least 20 seconds, rinse thoroughly with clean water, dry with clean towel or air dry", "Benefits of regular hand washing: kills germs and bacteria, prevents diseases (diarrhea, flu, cholera, typhoid, worms), stops spread of infections, keeps hands clean and healthy, prevents eye infections, protects from food poisoning", "Hand washing is one of the best ways to stay healthy", "Using hand sanitizer when soap and water not available"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,512) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-health-habits-t3-w8','ng-scheme-2025-preprimary-primary','N3','health-habits',3,'8',8,'teaching',null,'Disease and Sickness: Meaning and Examples','["Meaning of disease: illness or sickness that affects how body works, makes us feel unwell", "Understanding difference between disease (specific illness) and sickness (general feeling unwell)", "Examples of common diseases: Skin diseases - rashes, ringworm, scabies, eczema; Stomach diseases - diarrhea, cholera, dysentery, typhoid fever; Parasitic diseases - malaria (from mosquitoes), guinea worm (from contaminated water); Infectious diseases - measles, chicken pox, mumps, whooping cough, tuberculosis; Other diseases - headache, toothache, fever, cough, cold/catarrh", "Symptoms vary by disease: fever, pain, weakness, rashes, vomiting, diarrhea, cough", "Understanding diseases make us feel bad and need treatment"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,513) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-health-habits-t3-w9','ng-scheme-2025-preprimary-primary','N3','health-habits',3,'9',9,'teaching',null,'Water-borne Diseases','["Understanding water-borne diseases: diseases caused by drinking dirty/contaminated water or contact with dirty water", "Common water-borne diseases: Cholera - severe diarrhea and vomiting, dehydration; Typhoid fever - high fever, stomach pain, headache; Dysentery - bloody diarrhea, stomach cramps; Diarrhea - frequent watery stool, stomach pain; Guinea worm - worm in body from drinking contaminated water; Hepatitis A - liver disease, yellow eyes and skin", "How diseases spread: drinking dirty water, eating food washed with dirty water, not washing hands, swimming in contaminated water", "Symptoms: diarrhea, vomiting, fever, stomach pain, weakness", "Prevention: drink only clean/boiled water, wash hands with soap, keep water covered, use clean water for cooking, proper toilet use", "Treatment: see doctor immediately, drink plenty of safe water (ORS), take prescribed medicine"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,513) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-health-habits-t3-w10','ng-scheme-2025-preprimary-primary','N3','health-habits',3,'10',10,'teaching',null,'Air-borne Diseases & Prevention and Treatment','["Air-borne diseases:", "Understanding air-borne diseases: spread through air when sick person coughs, sneezes, or breathes", "Common air-borne diseases: Common cold - runny nose, cough, sneezing; Influenza (flu) - fever, cough, body ache, headache; Tuberculosis (TB) - persistent cough, chest pain, weight loss; Measles - fever, rash, cough, red eyes; Chicken pox - fever, itchy spots/blisters; Whooping cough - severe coughing fits; Mumps - swollen cheeks and jaw", "How diseases spread: breathing same air as sick person, coughing/sneezing without covering mouth, close contact with sick person Prevention and Treatment:", "Prevention: covering mouth when coughing/sneezing, washing hands frequently, avoiding close contact with sick people, keeping environment clean, good ventilation (fresh air), immunization/vaccination, eating healthy food (strong immune system), getting enough rest", "Treatment: seeing doctor, taking prescribed medicine, resting, drinking plenty of fluids, eating nutritious food, staying away from others to prevent spread, completing medication course"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,514) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-health-habits-t3-w11','ng-scheme-2025-preprimary-primary','N3','health-habits',3,'11',11,'revision',null,'Revision of Third Term & Year''s Work','["Third Term Review:", "Sanitation comprehensive review", "Hot and cold weather care", "Hand washing importance and technique", "Diseases, water-borne and air-borne", "Prevention and treatment strategies Year-Long Comprehensive Review:", "First Term: exercise, body care, teeth care, sleep, eating habits", "Second Term: waste disposal, composting, recycling, toilet hygiene, sanitation", "Third Term: weather care, hand washing, diseases", "All health habits and practices", "Mock examination exercises", "Reinforcing importance of good health habits"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,514) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-health-habits-t3-w12','ng-scheme-2025-preprimary-primary','N3','health-habits',3,'12',12,'examination',null,'End of Year Examination','["Third Term Assessment:", "Sanitation knowledge test", "Weather care assessment", "Hand washing technique and benefits", "Diseases identification test", "Water-borne and air-borne diseases", "Prevention and treatment knowledge Comprehensive Year Assessment:", "Personal hygiene and body care", "Exercise and sleep importance", "Eating habits (good and bad)", "Waste management and environmental health", "Toilet hygiene and sanitation", "Disease prevention and health protection", "Overall health consciousness", "Practical health habits demonstration", "Complete Nursery 3 health habits mastery"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,514) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-health-habits-t3-w13','ng-scheme-2025-preprimary-primary','N3','health-habits',3,'13',13,'closing',null,'Closing, Promotion & Graduation Activities','[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,515) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-social-habits-t1-w1','ng-scheme-2025-preprimary-primary','N3','social-habits',1,'1',1,'teaching',null,'My Rights: Children''s Rights','["Understanding rights: things every child deserves and should have", "Basic children''s rights: right to life, right to education (go to school), right to healthcare (see doctor when sick), right to food and shelter, right to love and care from parents, right to play and rest, right to protection from harm and abuse, right to express opinions, right to name and identity, right to clean water and environment", "Understanding rights come with responsibilities", "Everyone has same rights regardless of gender, tribe, or religion", "Understanding adults must respect and protect children''s rights", "Knowing who to tell if rights are violated"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,516) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-social-habits-t1-w2','ng-scheme-2025-preprimary-primary','N3','social-habits',1,'2',2,'teaching',null,'Child Abuse','["Meaning of child abuse: when someone hurts or harms a child physically, emotionally, or in other ways", "Understanding abuse is wrong and harmful", "Types of people who might abuse: can be anyone - family members, strangers, neighbors, even other children", "Understanding abuse is never the child''s fault", "Basic understanding that abuse violates children''s rights", "Difference between discipline and abuse", "Understanding children should feel safe at home, school, and everywhere", "Knowing abuse should be reported to trusted adults"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,516) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-social-habits-t1-w3','ng-scheme-2025-preprimary-primary','N3','social-habits',1,'3',3,'teaching',null,'Forms of Child Abuse','["Physical abuse: hitting, beating, burning, shaking, causing physical injury", "Emotional/psychological abuse: constant shouting, threatening, making child feel worthless, calling bad names", "Neglect: not providing food, clothes, shelter, medical care, education, love", "Sexual abuse: inappropriate touching or actions (age-appropriate explanation)", "Child labor: making children do dangerous or excessive work instead of going to school", "Bullying: repeated hurting by other children", "Understanding all forms of abuse are wrong", "Recognizing signs of abuse in self or others", "Understanding difference between appropriate and inappropriate touch"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,516) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-social-habits-t1-w4','ng-scheme-2025-preprimary-primary','N3','social-habits',1,'4',4,'teaching',null,'Prevention of Child Abuse','["How to protect yourself: knowing and using your name, knowing parents'' names and phone numbers, not going with strangers, not accepting gifts from strangers, telling trusted adults if someone makes you uncomfortable, saying \"NO\" to inappropriate touch, running away and shouting if in danger", "Safe and unsafe touches: safe touches (handshake, pat on back, hug from family) vs unsafe touches (touching private parts, hurting touches)", "Private parts are private: only parents/doctors (with parent present) should see/touch for health reasons", "Trusted adults: parents, teachers, school counselor, police, relatives you know well", "Understanding it''s okay to tell even if someone says it''s a secret", "No one should tell you to keep \"bad secrets\"", "Role-playing safety scenarios"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,517) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-social-habits-t1-w5','ng-scheme-2025-preprimary-primary','N3','social-habits',1,'5',5,'midterm_assessment',null,'Mid-term Assessment/test','["Children''s rights identification test", "Understanding of child abuse assessment", "Forms of abuse recognition test", "Prevention strategies evaluation", "Safety awareness assessment", "Oral questions on protection and rights"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,517) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-social-habits-t1-w6','ng-scheme-2025-preprimary-primary','N3','social-habits',1,'6',6,'midterm_break',null,'Mid-term Break','[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,517) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-social-habits-t1-w7','ng-scheme-2025-preprimary-primary','N3','social-habits',1,'7',7,'teaching',null,'Stigmatization: Meaning and Effects','["Meaning of stigmatization: treating someone badly or differently because of something about them (appearance, health condition, background, ability)", "Examples of stigmatization: making fun of children with disabilities, avoiding children with certain illnesses, treating orphans differently, rejecting children because of their tribe or religion, bullying children who look different", "Why people stigmatize: lack of understanding, fear, ignorance, prejudice", "Effects of stigmatization on victims: sadness, loneliness, low self-esteem, feeling rejected, not wanting to go to school, anger, health problems from stress", "Understanding stigmatization is wrong and hurts people", "Everyone deserves respect regardless of differences", "We should be kind to everyone"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,517) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-social-habits-t1-w8','ng-scheme-2025-preprimary-primary','N3','social-habits',1,'8',8,'teaching',null,'Equality and Fairness: Meaning and Importance','["Meaning of fairness: treating everyone in the same right way, being just", "Meaning of equality: everyone having same rights, opportunities, and treatment", "Understanding equality: boys and girls are equal, all children deserve same respect, no tribe or religion is better than another, children with disabilities have same rights", "Examples of fairness: sharing equally, taking turns, following same rules for everyone, giving everyone chance to participate", "Examples of unfairness: favoritism, discrimination, giving some children more than others without reason", "Importance of fairness and equality: makes everyone happy, creates peace, prevents conflicts, shows respect, follows God''s teaching, builds strong community", "Practicing fairness in daily life: at home, school, and play"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,518) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-social-habits-t1-w9','ng-scheme-2025-preprimary-primary','N3','social-habits',1,'9',9,'teaching',null,'Traditional Practices','["Understanding traditional practices: customs, beliefs, and behaviors passed down from ancestors/elders", "Examples of good traditional practices: greetings and respect for elders, traditional festivals and celebrations, traditional music and dances, traditional foods and recipes, traditional marriages and naming ceremonies, traditional crafts and arts, traditional medicine (some helpful remedies), communal living and helping neighbors", "Importance of preserving good traditions: connects us to our heritage, teaches values, maintains cultural identity, brings community together", "Understanding traditions vary by tribe, region, and religion", "Respecting different traditions while maintaining our own"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,518) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-social-habits-t1-w10','ng-scheme-2025-preprimary-primary','N3','social-habits',1,'10',10,'teaching',null,'Harmful Traditional Practices','["Harmful Traditional Practices:", "Understanding some old practices are harmful and should stop", "Examples of harmful practices: child marriage (children are too young to marry), female genital mutilation (FGM), preferring boys over girls, widowhood practices that harm women, denying girls education, child labor in name of tradition", "Why these are harmful: hurt children, violate rights, cause health problems, prevent education and growth", "Understanding harmful practices should be stopped even if \"traditional\"", "Modern laws protect children from harmful practices"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,518) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-social-habits-t1-w11','ng-scheme-2025-preprimary-primary','N3','social-habits',1,'11',11,'teaching',null,'Public Places','["Public Places:", "Understanding public places: areas used by everyone in community", "Examples: markets, parks, hospitals, churches/mosques, bus stops, libraries, community centers, streets", "These places belong to everyone", "Importance of respecting public spaces"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,519) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-social-habits-t1-w12','ng-scheme-2025-preprimary-primary','N3','social-habits',1,'12',12,'examination',null,'End of Term Examination','["Children''s rights comprehensive test", "Child abuse knowledge assessment", "Prevention strategies test", "Stigmatization understanding evaluation", "Equality and fairness assessment", "Traditional practices test", "Overall social awareness evaluation", "Safety consciousness assessment"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,519) on conflict (id) do nothing;
