insert into curriculum_topics values ('N3-social-habits-t2-w1','ng-scheme-2025-preprimary-primary','N3','social-habits',2,'1',1,'teaching',null,'Good Behaviour in Public Places','["Importance of good behavior in public places: shows respect, makes places pleasant for everyone, shows good upbringing, represents family and school well", "Good behaviors in different public places: Markets - staying with adults, not touching everything, speaking politely; Parks - not littering, taking turns on equipment, not destroying plants; Churches/Mosques - being quiet, showing respect, following rules; Hospitals - being quiet, not running, showing care; Bus stops/vehicles - queuing properly, giving seats to elderly/pregnant women, not pushing; Streets - using pedestrian crossings, not littering, greeting people politely", "General good behaviors: saying please and thank you, not shouting, queuing properly, respecting others'' space, being clean and neat, helping others when possible"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,519) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-social-habits-t2-w2','ng-scheme-2025-preprimary-primary','N3','social-habits',2,'2',2,'teaching',null,'Peace Education: How to Live Peacefully with Others','["Understanding peace: living together without fighting, violence, or conflicts", "How to live peacefully: being kind and friendly, sharing with others, respecting differences (tribe, religion, culture), helping those in need, forgiving when someone wrongs you, using words instead of fighting, taking turns, listening to others, obeying rules and authority, controlling anger", "Resolving conflicts peacefully: talking about problems, saying sorry when wrong, asking adults to help settle disputes, compromising (both sides giving a little)", "Reasons for living in peace: happiness for everyone, safety and security, better learning and growth, stronger friendships, good health (less stress), community development, showing love for God", "Understanding peace starts with each person''s choices", "\"Blessed are the peacemakers\""]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,520) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-social-habits-t2-w3','ng-scheme-2025-preprimary-primary','N3','social-habits',2,'3',3,'teaching',null,'Endurance and Tolerance','["Meaning of endurance: ability to bear difficult situations patiently without giving up", "Meaning of tolerance: accepting and respecting people who are different from us (different opinions, cultures, religions, appearances)", "Understanding tolerance is NOT accepting wrong behavior, but respecting differences", "Examples of endurance: staying calm when provoked, completing difficult tasks, waiting patiently, bearing with others'' weaknesses", "Examples of tolerance: playing with children of all tribes, respecting different religions, accepting children with disabilities, listening to different opinions", "How endurance and tolerance lead to peaceful co-existence: fewer conflicts, better understanding, stronger relationships, united community, reduced violence", "Practicing endurance and tolerance daily"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,520) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-social-habits-t2-w4','ng-scheme-2025-preprimary-primary','N3','social-habits',2,'4',4,'teaching',null,'Our Neighbours: Meaning and Peace with Neighbours','["Meaning of neighbour: people living near us (next house, same street, same community)", "Understanding \"neighbour\" also means anyone near us or needing help", "Types of neighbours: those living in same compound, same street, same neighborhood, classmates at school, people we meet regularly", "Why we should be at peace with neighbours: we live close together, we see each other often, we may need help from each other, conflicts affect everyone, peace makes community better, God commands us to love our neighbors, emergency situations need cooperation", "How to live peacefully with neighbours: greeting them respectfully, not making too much noise, respecting their property, being helpful, resolving conflicts quickly, not gossiping, celebrating together, sharing when possible", "Good neighbor parable/story"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,521) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-social-habits-t2-w5','ng-scheme-2025-preprimary-primary','N3','social-habits',2,'5',5,'midterm_assessment',null,'Mid-term Assessment/test','["Public behavior knowledge test", "Peace education assessment", "Endurance and tolerance understanding", "Neighborliness evaluation", "Practical scenarios test", "Social skills observation"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,521) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-social-habits-t2-w6','ng-scheme-2025-preprimary-primary','N3','social-habits',2,'6',6,'midterm_break',null,'Mid-term Break','[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,521) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-social-habits-t2-w7','ng-scheme-2025-preprimary-primary','N3','social-habits',2,'7',7,'teaching',null,'Emotions: Meaning, Types, and Reasons','["Meaning of emotions: feelings we experience, how we feel inside", "Understanding emotions are normal, everyone has them", "Types of emotions: Positive emotions - happiness/joy, love, excitement, pride, gratitude, peace, hope; Negative emotions - sadness, anger, fear, worry, jealousy, loneliness, shame", "Reasons for different emotions: happy when good things happen (birthday, passed exam, made friends), sad when bad things happen (lost something, failed, someone died), angry when treated unfairly or frustrated, afraid when in danger or facing unknown, excited when anticipating something good, worried when facing problems or uncertainty", "Understanding emotions change and don''t last forever", "It''s okay to have negative emotions but must express appropriately", "Healthy ways to express emotions: talking to trusted adults, crying when sad (not shameful), exercising, drawing, playing", "Unhealthy ways: hitting others, breaking things, hurting self"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,521) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-social-habits-t2-w8','ng-scheme-2025-preprimary-primary','N3','social-habits',2,'8',8,'teaching',null,'Personal Beautification: Hairstyling','["Understanding personal beautification: making ourselves look neat, clean, and attractive", "Importance of neat appearance: shows self-respect, makes good impression, shows discipline", "Types of hairdo for girls: ponytails, braids (single, double, multiple), cornrows, twists, buns, afro puff, weaving (with extensions), loose hair (combed neatly), decorated with ribbons/clips", "Types of haircut for boys: low cut, high cut, skin cut, crew cut, fade, natural afro (shaped), shaped designs", "Hair care: washing regularly, combing daily, oiling/moisturizing, keeping neat and tidy, appropriate styles for school vs special occasions", "Understanding hairstyles vary by culture", "School usually requires simple, neat hairstyles", "Beauty is not just outward appearance but also character"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,522) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-social-habits-t2-w9','ng-scheme-2025-preprimary-primary','N3','social-habits',2,'9',9,'teaching',null,'States and Their Capitals','["Understanding Nigeria has 36 states plus Federal Capital Territory (FCT)", "States and capitals (by geopolitical zones): South-West: Lagos-Ikeja, Ogun-Abeokuta, Oyo- Ibadan, Osun-Oshogbo, Ondo-Akure, Ekiti-Ado- Ekiti South-East: Abia-Umuahia, Anambra-Awka, Ebonyi-Abakaliki, Enugu-Enugu, Imo-Owerri South-South: Akwa Ibom-Uyo, Bayelsa-Yenagoa, Cross River-Calabar, Delta-Asaba, Edo-Benin City, Rivers-Port Harcourt North-Central: Benue-Makurdi, Kogi-Lokoja, Kwara-Ilorin, Nasarawa-Lafia, Niger-Minna, Plateau-Jos, FCT-Abuja North-East: Adamawa-Yola, Bauchi-Bauchi, Borno-Maiduguri, Gombe-Gombe, Taraba-Jalingo, Yobe-Damaturu North-West: Jigawa-Dutse, Kaduna-Kaduna, Kano-Kano, Katsina-Katsina, Kebbi-Birnin Kebbi, Sokoto-Sokoto, Zamfara-Gusau", "Federal Capital Territory: Abuja", "Understanding capital cities are centers of government", "Map of Nigeria showing states"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,522) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-social-habits-t2-w10','ng-scheme-2025-preprimary-primary','N3','social-habits',2,'10',10,'teaching',null,'State Leaders','["State Leaders:", "Understanding each state has leaders who govern", "State Governor: chief executive of state, makes laws with State House of Assembly", "Deputy Governor: assists governor", "State House of Assembly: makes laws for state", "Local Government Chairmen: lead local government areas", "Traditional rulers in states: Obas, Emirs, Chiefs"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,523) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-social-habits-t2-w11','ng-scheme-2025-preprimary-primary','N3','social-habits',2,'11',11,'teaching',null,'Nigeria, My Country','["Nigeria, My Country:", "Identification of Nigeria: our country, in West Africa, most populous African country", "National symbols: flag (green-white-green), coat of arms, national anthem, pledge", "Description of Coat of Arms: black shield, two white horses, eagle on top, red flowers, Y-shaped band (rivers Niger and Benue)", "Motto: \"Unity and Faith, Peace and Progress\"", "Understanding coat of arms represents our nation", "Pride in being Nigerian"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,523) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-social-habits-t2-w12','ng-scheme-2025-preprimary-primary','N3','social-habits',2,'12',12,'examination',null,'End of Term Examination','["Public behavior test", "Peace and tolerance assessment", "Emotions knowledge test", "Personal grooming evaluation", "States and capitals comprehensive test", "State leaders identification", "Nigeria knowledge assessment", "Overall social studies evaluation"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,523) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-social-habits-t2-w13','ng-scheme-2025-preprimary-primary','N3','social-habits',2,'13',13,'closing',null,'Closing & End of Term Activities','["Return of examination scripts", "Distribution of report cards", "Social studies excellence celebration", "Awards for peacemaking and good citizenship", "Nigerian culture appreciation day", "Preview of third term topics", "Holiday activities and tips"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,524) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-social-habits-t3-w1','ng-scheme-2025-preprimary-primary','N3','social-habits',3,'1',1,'teaching',null,'Parental Care: Meaning and Forms','["Meaning of parental care: love, protection, guidance, and provision that parents/guardians give to children", "Understanding parental care is essential for children''s development", "Forms of parental care: Physical care - providing food, shelter, clothes, medical care; Emotional care - showing love, affection, encouragement, spending time together; Educational care - sending to school, helping with homework, providing school needs; Spiritual care - teaching about God, praying for children, taking to religious services; Social care - teaching good behavior, manners, how to relate with others; Protection - keeping children safe from harm, abuse, danger; Discipline - correcting wrong behavior with love, teaching right from wrong; Financial provision - providing money for needs", "Different caregivers: parents, grandparents, foster parents, adoptive parents, guardians"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,525) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-social-habits-t3-w2','ng-scheme-2025-preprimary-primary','N3','social-habits',3,'2',2,'teaching',null,'Parental Care: Reasons Children Need It & Causes of Lack','["Reasons children need parental care: children cannot care for themselves, need guidance to grow properly, need love for emotional health, need protection from danger, need education for future, need spiritual guidance, need socialization skills, develop better with parental care", "What happens without parental care: poor health and nutrition, emotional problems, involvement in crime, dropping out of school, exploitation and abuse, low self-esteem, difficulty relating with others", "Causes of lack of parental care: death of parent(s), parents working far away, poverty (parents too busy working), parental neglect/irresponsibility, divorce/separation of parents, parental illness, parental addiction (drugs/alcohol), imprisonment of parents, parents not knowing importance of care", "Understanding some children lack proper care through no fault of their own", "Community and government should help such children"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,525) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-social-habits-t3-w3','ng-scheme-2025-preprimary-primary','N3','social-habits',3,'3',3,'teaching',null,'Violence: Physical Violence Against Children','["Meaning of violence: use of force to harm or hurt someone", "Meaning of physical violence against children: hurting children''s bodies through beating, hitting, slapping, kicking, pushing, burning, etc", "Forms of physical violence: excessive corporal punishment, beating with dangerous objects, slapping faces, burning with hot objects, pushing down stairs, shaking babies/small children, denying food as punishment, locking in dark rooms, tying up children", "Understanding discipline ≠ violence: appropriate discipline is correction with love, doesn''t cause injury or trauma", "Effects of physical violence: physical injuries (bruises, broken bones, burns), pain and suffering, fear and trauma, health problems, poor school performance, aggressive behavior, low self-esteem, running away from home, death (in extreme cases)", "Violence is wrong and illegal", "Children should report physical violence to trusted adults"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,526) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-social-habits-t3-w4','ng-scheme-2025-preprimary-primary','N3','social-habits',3,'4',4,'teaching',null,'Violence: Mental/emotional Violence Against Children','["Meaning of mental/emotional violence: hurting children''s feelings, mind, and emotions through words or actions", "Forms of mental violence: constant shouting and yelling, calling children bad names (stupid, useless, worthless), comparing unfavorably with others, threatening to abandon or kill, showing no love or affection, ignoring children''s needs, excessive criticism, ridiculing in public, making children feel unwanted, blaming children for adult problems, exposing to scary situations deliberately", "Effects of mental violence: low self-esteem, depression and sadness, anxiety and fear, difficulty trusting others, poor academic performance, social withdrawal, behavioral problems, anger issues, difficulty forming relationships, long-term psychological damage", "Understanding words can hurt as much as physical violence", "Some effects last into adulthood", "Children deserve encouragement and love", "Reporting emotional abuse"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,526) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-social-habits-t3-w5','ng-scheme-2025-preprimary-primary','N3','social-habits',3,'5',5,'midterm_assessment',null,'Mid-term Assessment/test','["Parental care knowledge test", "Understanding of violence assessment", "Effects of violence evaluation", "Child protection awareness test", "Identifying forms of abuse", "Safety and reporting mechanisms"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,527) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-social-habits-t3-w6','ng-scheme-2025-preprimary-primary','N3','social-habits',3,'6',6,'midterm_break',null,'Mid-term Break','[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,527) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-social-habits-t3-w7','ng-scheme-2025-preprimary-primary','N3','social-habits',3,'7',7,'teaching',null,'Orphans and Vulnerable Children','["Understanding orphans: children who have lost one or both parents", "Types of orphans: paternal orphan (lost father), maternal orphan (lost mother), double orphan (lost both parents)", "Understanding vulnerable children: children at high risk of abuse, neglect, or exploitation", "Who are vulnerable children: orphans, children with sick parents, street children, children with disabilities, children in extreme poverty, refugee children, abandoned children, children living with elderly caregivers", "Challenges faced: lack of basic needs, no education, exploitation, abuse, discrimination, emotional trauma, lack of guidance", "How to help: showing kindness, not discriminating, government support programs, orphanages, adoption/foster care, community support, NGO interventions, sponsorship programs", "Understanding orphans and vulnerable children deserve same rights and opportunities", "Being kind to vulnerable children in school and community"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,527) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-social-habits-t3-w8','ng-scheme-2025-preprimary-primary','N3','social-habits',3,'8',8,'teaching',null,'Children with Special Needs','["Understanding children with special needs: children with physical, mental, or developmental challenges that require extra support", "Types of special needs: Visually impaired - cannot see well or at all, may use white canes, braille, guide dogs; Hearing impaired - cannot hear well or at all, may use hearing aids, sign language; Physically handicapped - difficulty moving, may use wheelchairs, crutches, prosthetic limbs; Autistic children - difficulty with communication and social interaction, may have repetitive behaviors; Learning disabilities - difficulty learning like other children; Speech impairment - difficulty speaking clearly", "Understanding these children are still valuable and capable", "How to treat children with special needs: with respect and kindness, not mocking or staring, offering help when needed, including them in activities, not using hurtful words (e.g., \"blind,\" \"cripple\" as insults), being patient, treating as equals", "Special schools and inclusive education", "Many successful people have disabilities"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,527) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-social-habits-t3-w9','ng-scheme-2025-preprimary-primary','N3','social-habits',3,'9',9,'teaching',null,'Care for Sick People','["Identification of sick people: showing symptoms (fever, coughing, weakness, pain), lying down often, not eating well, looking pale or tired, vomiting, having rashes, moving slowly", "Understanding sickness is temporary, person will get better", "How to care for sick people: Practical care - helping them rest, getting them water or food, fetching their medicine (with adult supervision), keeping environment quiet, opening windows for fresh air; Emotional care - showing love and concern, visiting them, talking to them, praying for them, not complaining about them, being patient; Hygiene - washing hands before and after helping, not sharing eating utensils, covering mouth when near sick person; Getting help - telling adults if person gets worse, calling doctor if emergency, helping sick person to clinic/hospital", "What NOT to do: disturbing their rest, making noise, giving them wrong medicine, being impatient", "Understanding caring for sick people shows compassion"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,528) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-social-habits-t3-w10','ng-scheme-2025-preprimary-primary','N3','social-habits',3,'10',10,'teaching',null,'Care and Respect for Old People','["Identification of old people: elderly, aged, senior citizens, grandparents, great-grandparents", "Physical signs: gray/white hair, wrinkled skin, walking slowly, may use walking sticks, may have difficulty seeing/hearing", "Understanding old people were once young and strong, deserve respect for their years", "Why respect old people: they have wisdom and experience, they cared for others when young, African culture values elders, religious teachings command respect, they are vulnerable and need help, they are blessings to families", "How to respect and care for old people: greeting them properly (kneeling/prostrating in some cultures), listening to their advice, speaking politely, not shouting at them, helping with tasks (carrying loads, fetching water), giving them seats, visiting them, not mocking their weakness, being patient, obeying them, protecting them from harm", "Old people''s homes for those without family care", "Understanding: \"Honor your father and mother that your days may be long\""]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,528) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-social-habits-t3-w11','ng-scheme-2025-preprimary-primary','N3','social-habits',3,'11',11,'revision',null,'Revision of Third Term & Year''s Work','["Third Term Review:", "Parental care comprehensive review", "Violence against children (physical and mental)", "Vulnerable children and orphans", "Children with special needs", "Care for sick and old people Year-Long Comprehensive Review:", "First Term: rights, abuse, stigmatization, equality, traditions", "Second Term: public behavior, peace, neighbors, emotions, Nigeria", "Third Term: all topics covered", "Complete social habits and citizenship education", "Mock examination exercises", "Practical scenarios and role-playing"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,529) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-social-habits-t3-w12','ng-scheme-2025-preprimary-primary','N3','social-habits',3,'12',12,'examination',null,'End of Year Examination','["Third Term Assessment:", "Parental care test", "Violence understanding and effects", "Vulnerable children knowledge", "Special needs awareness", "Care for sick and elderly assessment Comprehensive Year Assessment:", "Children''s rights and protection", "Peace and tolerance", "Nigerian citizenship", "Compassion and caregiving", "Social responsibility", "Overall Nursery 3 social habits mastery", "Character and values assessment", "Community awareness evaluation"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,529) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-social-habits-t3-w13','ng-scheme-2025-preprimary-primary','N3','social-habits',3,'13',13,'closing',null,'Closing, Promotion & Graduation Activities','[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,530) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-civic-education-t1-w1','ng-scheme-2025-preprimary-primary','N3','civic-education',1,'1',1,'teaching',null,'Gender Issues: Identification of Self As Male or Female','["Understanding gender: male (boy/man) and female (girl/woman)", "Identifying self: \"I am a boy\" or \"I am a girl\"", "Physical differences (age-appropriate): boys and girls have different body parts", "Understanding both genders are equally important and valuable", "Boys can become fathers/men, girls can become mothers/women", "Understanding gender from birth, not a choice", "Respecting both genders", "Understanding everyone deserves respect regardless of gender"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,531) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-civic-education-t1-w2','ng-scheme-2025-preprimary-primary','N3','civic-education',1,'2',2,'teaching',null,'Gender Issues: Equality of Genders','["Understanding boys and girls are equal in value and importance", "Both genders can do most things: go to school, play, learn, work, lead", "No job or activity is only for boys or only for girls", "Girls can be doctors, pilots, leaders; boys can be nurses, teachers, cooks", "Both should have same opportunities and rights", "Understanding gender stereotypes are wrong: \"boys don''t cry,\" \"girls can''t play football\"", "Respecting and treating both genders fairly", "Understanding God created both male and female in His image"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,531) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-civic-education-t1-w3','ng-scheme-2025-preprimary-primary','N3','civic-education',1,'3',3,'teaching',null,'Gender Issues in Games and Plays: Male and Female Children Playing Together','["Understanding boys and girls can and should play together", "Games for everyone: football, hide and seek, tag, skipping, dancing, singing", "No game is only for boys or only for girls", "Benefits of playing together: making more friends, learning from each other, developing social skills, having more fun, breaking stereotypes, learning teamwork", "Playing fairly with everyone regardless of gender", "Including everyone in games", "Not bullying or excluding based on gender", "Understanding cooperation between genders is important"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,531) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-civic-education-t1-w4','ng-scheme-2025-preprimary-primary','N3','civic-education',1,'4',4,'teaching',null,'Folk Tales for Male and Female: Meaning and Importance','["Meaning of folk tales: traditional stories passed down from ancestors, usually with moral lessons", "Understanding folk tales are for everyone: boys and girls, men and women", "Examples of Nigerian folk tales: Tortoise and his cunning ways, Why the Sky is Far Away, The Greedy Lion, Anansi the Spider stories", "Folk tales featuring both male and female characters", "Importance of folk tales: teach moral lessons (honesty, kindness, wisdom), preserve culture and traditions, entertain and educate, teach consequences of actions, connect us to our heritage, teach values to children", "Learning from characters regardless of their gender", "Understanding folk tales teach everyone important lessons"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,532) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-civic-education-t1-w5','ng-scheme-2025-preprimary-primary','N3','civic-education',1,'5',5,'midterm_assessment',null,'Mid-term Assessment/test','["Gender identification test", "Gender equality understanding assessment", "Inclusive play knowledge test", "Folk tales understanding evaluation", "Moral lessons from stories test", "Oral questions on gender and culture"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,532) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-civic-education-t1-w6','ng-scheme-2025-preprimary-primary','N3','civic-education',1,'6',6,'midterm_break',null,'Mid-term Break','[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,532) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-civic-education-t1-w7','ng-scheme-2025-preprimary-primary','N3','civic-education',1,'7',7,'teaching',null,'Love for One''s Country (Nigeria)','["Understanding what it means to love your country: feeling proud, caring about it, wanting it to be better", "How to love Nigeria: respecting national symbols (flag, anthem, coat of arms), obeying laws and rules, keeping environment clean, not littering, paying attention in school (education builds the nation), respecting leaders and elders, being peaceful and not fighting, helping others in community, not destroying public property, speaking well of Nigeria, learning about Nigerian culture and history", "Understanding patriotism: love and devotion to one''s country", "Nigeria is our home, we must care for it", "Understanding we are all Nigerians regardless of tribe or religion", "\"Unity and Faith, Peace and Progress\""]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,532) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-civic-education-t1-w8','ng-scheme-2025-preprimary-primary','N3','civic-education',1,'8',8,'teaching',null,'National Colours & National Song (Anthem)','["National Colours:", "Official colours of Nigeria: Green and White", "Description of Nigerian flag: two green stripes on sides, one white stripe in middle (vertical stripes)", "Meaning of colours: Green represents agriculture/forests (rich land), White represents peace and unity", "When flag is displayed: government buildings, schools, national events, Independence Day, international events", "Respecting the flag: standing when raised, not tearing or destroying National Song:", "Nigeria National Anthem (first verse): \"Arise, O compatriots, Nigeria''s call obey To serve our fatherland, With love and strength and faith The labour of our heroes past, Shall never be in vain To serve with heart and might, One nation bound in freedom, peace and unity\"", "When anthem is sung: national events, school assembly, competitions", "Standing at attention during anthem", "Understanding anthem''s message: serve Nigeria, unity, freedom"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,533) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-civic-education-t1-w9','ng-scheme-2025-preprimary-primary','N3','civic-education',1,'9',9,'teaching',null,'Responsibilities As Children: Things We Must Do','["Understanding responsibilities: duties, things we should do", "Children''s responsibilities: obeying parents and teachers, doing homework and schoolwork, helping with house chores (age-appropriate), keeping self and environment clean, being honest and truthful, respecting elders and peers, taking care of belongings, eating healthy food, sleeping early, going to school regularly, playing safely, reporting danger to adults, being kind to others, following rules", "Understanding responsibilities prepare us for adulthood", "Everyone has responsibilities regardless of age", "Doing responsibilities without being forced", "Understanding rights come with responsibilities"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,533) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-civic-education-t1-w10','ng-scheme-2025-preprimary-primary','N3','civic-education',1,'10',10,'teaching',null,'Children''s Rights & Basic Amenities','["Children''s Rights:", "Review of rights from Social Habits: education, healthcare, food, shelter, protection, love, play, name/identity, expression", "Understanding rights are what we deserve", "Adults must protect children''s rights", "Balance between rights and responsibilities Basic Amenities:", "Understanding basic amenities: essential services and facilities needed for comfortable living", "Examples: clean water, electricity, good roads, schools, hospitals/clinics, toilets, drainage systems, waste disposal, security, recreational facilities (parks, playgrounds)", "Importance: make life easier, keep us healthy, help development, improve quality of life", "Government''s responsibility to provide amenities", "Citizens should not destroy public amenities", "Using amenities properly and responsibly"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,534) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-civic-education-t1-w11','ng-scheme-2025-preprimary-primary','N3','civic-education',1,'11',11,'revision',null,'Revision of First Term Work','["Gender issues comprehensive review", "Gender equality and inclusive play", "Folk tales and their importance", "Love for Nigeria and patriotism", "National colours, flag, and anthem", "Children''s responsibilities", "Children''s rights", "Basic amenities understanding", "Mock examination exercises", "Singing national anthem practice"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,534) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-civic-education-t1-w12','ng-scheme-2025-preprimary-primary','N3','civic-education',1,'12',12,'examination',null,'End of Term Examination','["Gender identification and equality test", "Inclusive play assessment", "Folk tales importance evaluation", "Patriotism and love for Nigeria test", "National symbols knowledge (flag, anthem)", "Children''s responsibilities comprehensive test", "Rights and amenities assessment", "Overall civic awareness evaluation"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,534) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-civic-education-t1-w13','ng-scheme-2025-preprimary-primary','N3','civic-education',1,'13',13,'closing',null,'Closing & End of Term Activities','["Return of examination scripts", "Distribution of report cards", "Civic education celebration", "Patriotic songs and activities", "Awards for good citizenship", "Holiday civic tips", "Preview of second term topics"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,535) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-civic-education-t2-w1','ng-scheme-2025-preprimary-primary','N3','civic-education',2,'1',1,'teaching',null,'Review of Responsibilities','["Comprehensive review of responsibilities from first term", "Understanding responsibilities in different places: home, school, community, religious places", "Importance of fulfilling responsibilities", "Understanding responsibilities show maturity and character", "Linking rights and responsibilities", "Preparing for specific responsibilities in different contexts"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,536) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-civic-education-t2-w2','ng-scheme-2025-preprimary-primary','N3','civic-education',2,'2',2,'teaching',null,'Responsibilities at Home: Things Children Should Do','["Understanding home responsibilities help family function well", "Children''s responsibilities at home: keeping room tidy, making bed after waking, putting away toys after play, helping set table for meals, helping clear table after eating, simple cleaning (sweeping with supervision), feeding pets (if any), putting dirty clothes in laundry basket, not wasting water/electricity, obeying parents, respecting siblings, doing homework, going to bed on time, taking care of younger siblings, running small errands", "Understanding home chores teach life skills", "Doing tasks without complaining", "Helping makes parents'' work easier", "Building responsibility from young age"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,536) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-civic-education-t2-w3','ng-scheme-2025-preprimary-primary','N3','civic-education',2,'3',3,'teaching',null,'Responsibilities in School: Things Children Should Do','["School responsibilities: arriving on time (punctuality), wearing proper uniform, bringing required materials (books, pencils), paying attention in class, doing classwork and homework, respecting teachers and classmates, following school rules, keeping classroom clean, returning borrowed items, taking care of school property, participating in activities, staying in designated areas, lining up properly, asking questions when don''t understand, helping classmates when appropriate, reporting problems to teachers", "Understanding school is for learning", "Good behavior helps everyone learn better", "School responsibilities prepare for future success"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,536) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-civic-education-t2-w4','ng-scheme-2025-preprimary-primary','N3','civic-education',2,'4',4,'teaching',null,'Responsibilities in Religious Places: Care for Personal Belongings','["Understanding religious places: churches, mosques, temples", "General responsibilities: arriving on time, dressing appropriately, being quiet and respectful, listening to teachings, participating in prayers/songs, following rules of worship place, greeting elders respectfully, not playing or running inside", "How to take care of personal belongings at places of worship: keeping shoes/slippers together, holding onto bags properly, not leaving items scattered, keeping religious books (Bible, Quran) clean and respectful, putting belongings in designated places, not losing items, asking adults for help if can''t find something, respecting others'' belongings", "Understanding religious places are sacred, deserve respect", "Being responsible even in religious settings"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,537) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-civic-education-t2-w5','ng-scheme-2025-preprimary-primary','N3','civic-education',2,'5',5,'midterm_assessment',null,'Mid-term Assessment/test','["Home responsibilities test", "School responsibilities assessment", "Religious place behavior evaluation", "Personal belongings care test", "Understanding of responsibilities in different contexts", "Practical scenarios assessment"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,537) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-civic-education-t2-w6','ng-scheme-2025-preprimary-primary','N3','civic-education',2,'6',6,'midterm_break',null,'Mid-term Break','[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,537) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-civic-education-t2-w7','ng-scheme-2025-preprimary-primary','N3','civic-education',2,'7',7,'teaching',null,'Rewards and Consequences & Government Property','["Rewards and Consequences:", "Rewards of performing responsibilities: praise and appreciation from parents/teachers, good grades in school, privileges (extra playtime, treats), developing good character, building self-confidence, learning life skills, respect from others, sense of achievement, preparing for adult life", "Consequences of not performing responsibilities: punishment or discipline, poor grades, loss of privileges, disappointment from parents/teachers, poor character development, difficulty in life, others won''t trust you, becoming irresponsible adult Government Property to Take Care Of:", "Understanding government property belongs to all citizens", "Examples: school buildings and furniture, hospitals and equipment, roads and bridges, street lights, public parks, water fountains, public toilets, government vehicles, traffic lights", "How to care for them: not destroying, not writing on walls, not littering, using properly, reporting damage", "Consequences of destroying: everyone suffers, government spends money to repair instead of building new things"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,537) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-civic-education-t2-w8','ng-scheme-2025-preprimary-primary','N3','civic-education',2,'8',8,'teaching',null,'Good Behaviour: Punctuality','["Meaning of punctuality: arriving early or on time for activities/appointments", "Understanding punctuality means not being late", "Examples of punctuality: arriving at school before bell rings, being ready for lessons on time, finishing work within given time, attending events at scheduled time", "Importance of punctuality: shows respect for others'' time, shows discipline and responsibility, prevents missing important information, shows good character, builds trust, prevents punishment, allows proper planning, professional behavior even as child, \"time is precious\"", "How to be punctual: preparing things night before, waking up early, not wasting time, being organized, leaving early enough", "Understanding \"punctuality is the soul of business\""]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,538) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-civic-education-t2-w9','ng-scheme-2025-preprimary-primary','N3','civic-education',2,'9',9,'teaching',null,'Good Behaviour: Obedience','["Meaning of obedience: doing what we are told by authority (parents, teachers, elders) without arguing or delay", "Understanding obedience is not slavery but respect for authority", "Who to obey: parents, teachers, school authorities, elders, police, government rules/laws, God''s commandments", "Importance of obedience: keeps us safe from danger, helps us learn, shows respect, brings blessings, prevents punishment, builds trust, develops good character, makes life easier, brings peace, \"obedience is better than sacrifice\"", "When not to obey: if asked to do something wrong, harmful, or immoral (should tell trusted adult)", "Understanding obedience to God is most important"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,538) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-civic-education-t2-w10','ng-scheme-2025-preprimary-primary','N3','civic-education',2,'10',10,'teaching',null,'Good Behaviour: Respect & Self- Control','["Respect:", "Meaning of respect: showing honor, consideration, and good manners to others", "Who deserves respect: everyone - elders, parents, teachers, peers, younger ones, authority figures, people of all tribes/religions", "How to show respect: proper greetings, using polite words, listening when others speak, not interrupting, obeying instructions, not mocking or insulting, respecting property, helping others", "Importance: maintains peace, shows good upbringing, earns respect in return, builds relationships, shows maturity Self-Control:", "Meaning: ability to control own emotions, actions, and desires", "Examples: not fighting when angry, not taking others'' things even when you want them, waiting your turn, not eating too much candy, stopping play when told, controlling temper", "Importance: prevents problems, shows maturity, earns trust, keeps us out of trouble, helps make good decisions"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,539) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-civic-education-t2-w11','ng-scheme-2025-preprimary-primary','N3','civic-education',2,'11',11,'revision',null,'Revision of Second Term Work','["All responsibilities review (home, school, religious places)", "Rewards and consequences understanding", "Government property care", "Good behavior traits: punctuality, obedience, respect, self-control", "Importance of each trait", "Practical examples and scenarios", "Mock examination exercises"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,539) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-civic-education-t2-w12','ng-scheme-2025-preprimary-primary','N3','civic-education',2,'12',12,'examination',null,'End of Term Examination','["Responsibilities comprehensive test (all contexts)", "Rewards and consequences assessment", "Government property knowledge", "Punctuality understanding test", "Obedience evaluation", "Respect and self-control assessment", "Good behavior traits comprehensive test", "Overall civic character evaluation"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,539) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-civic-education-t2-w13','ng-scheme-2025-preprimary-primary','N3','civic-education',2,'13',13,'closing',null,'Closing & End of Term Activities','["Return of examination scripts", "Distribution of report cards", "Good character celebration", "Awards for punctuality, obedience, respect", "Character development recognition", "Holiday behavior reminders", "Preview of third term topics"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,540) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-civic-education-t3-w1','ng-scheme-2025-preprimary-primary','N3','civic-education',3,'1',1,'teaching',null,'Orderliness at Home','["Meaning of orderliness: keeping things organized, neat, and in their proper places; doing things in proper sequence", "Orderliness at home: keeping room tidy, arranging toys and books properly, putting clothes in wardrobe/drawer, shoes in shoe rack, keeping bed neat, helping keep house clean, putting things back after use, not scattering items around, washing dishes orderly (if helping), eating meals at proper times, following bedtime routine, organizing schoolwork", "Importance: easy to find things, prevents accidents (tripping), shows discipline, makes home beautiful, reduces stress, shows respect for family, saves time, develops good habits", "Understanding \"cleanliness is next to godliness\"", "Orderliness is everyone''s responsibility"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,541) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-civic-education-t3-w2','ng-scheme-2025-preprimary-primary','N3','civic-education',3,'2',2,'teaching',null,'Orderliness at School','["Orderliness at school: arranging desk and books neatly, lining up properly, entering/leaving classroom orderly, keeping classroom clean, putting away learning materials after use, organizing school bag, turning in work on time, raising hand before speaking, taking turns, following instructions in sequence, putting waste in bins, keeping locker organized, wearing uniform properly", "Importance: enhances learning, prevents confusion, shows discipline, maintains safety, creates pleasant environment, shows respect for teachers and classmates, develops organizational skills", "Class prefects help maintain orderliness", "Everyone must cooperate for orderly school"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,541) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-civic-education-t3-w3','ng-scheme-2025-preprimary-primary','N3','civic-education',3,'3',3,'teaching',null,'Orderliness in the Community','["Understanding community: neighborhood, village, town where we live", "Orderliness in community: keeping streets clean, not littering, proper waste disposal, queuing at bus stops/shops, obeying traffic rules (as pedestrians), respecting public property, parking in designated areas (for adults), organized markets, peaceful behavior, respecting community rules, participating in community cleanup, organized events and programs", "Importance: beautiful environment, prevents diseases, makes community pleasant, attracts development, shows civilization, maintains peace, reflects well on residents", "Everyone''s role in community orderliness", "Understanding orderly community prospers"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,541) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-civic-education-t3-w4','ng-scheme-2025-preprimary-primary','N3','civic-education',3,'4',4,'teaching',null,'Honesty at Home: How to Show Honesty','["Review of honesty meaning: always telling truth, not lying, cheating, or stealing", "How to show honesty at home: telling truth always even when afraid of punishment, admitting mistakes, not blaming siblings for what you did, not stealing from parents or siblings, not taking money without permission, returning things borrowed, keeping promises, not hiding bad behavior, saying where you''re going, honest about homework (did it or not), not exaggerating stories", "Benefits at home: parents trust you, peace in family, good example to siblings, clear conscience, builds character, earns privileges, maintains harmony", "Understanding honesty starts at home"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,542) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-civic-education-t3-w5','ng-scheme-2025-preprimary-primary','N3','civic-education',3,'5',5,'midterm_assessment',null,'Mid-term Assessment/test','["Orderliness understanding test (home, school, community)", "Honesty at home assessment", "Practical scenarios evaluation", "Character traits demonstration", "Values understanding test"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,542) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-civic-education-t3-w6','ng-scheme-2025-preprimary-primary','N3','civic-education',3,'6',6,'midterm_break',null,'Mid-term Break','[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,542) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-civic-education-t3-w7','ng-scheme-2025-preprimary-primary','N3','civic-education',3,'7',7,'teaching',null,'Honesty at School & in the Community','["Honesty at School:", "How to show: not cheating in tests/exams, doing own work, admitting when you don''t understand, returning borrowed items, not lying to teachers, honest about attendance, not stealing classmates'' things, admitting mistakes, honest in group work, giving credit where due", "Benefits: good grades reflect real ability, teachers trust you, good reputation, clear conscience, real learning happens Honesty in Community:", "How to show: returning found items to owner or authority, not stealing from neighbors/shops, telling truth about what you saw, honest in business dealings (even as child buying things), admitting fault when damage something, keeping promises to friends", "Advantages of honesty: people trust you, good reputation, peace of mind, attracts blessings, earns respect, stays out of trouble, develops integrity, \"honesty is the best policy,\" God rewards honesty"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,542) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-civic-education-t3-w8','ng-scheme-2025-preprimary-primary','N3','civic-education',3,'8',8,'teaching',null,'Cooperation at Home','["Meaning of cooperation: working together toward common goal, helping each other", "Cooperation at home: helping parents with chores, assisting siblings, working together to keep house clean, sharing responsibilities, helping each other with homework, caring for younger siblings together, supporting each other, participating in family activities, resolving conflicts peacefully, team effort in family projects", "Benefits: work gets done faster and easier, stronger family bonds, pleasant home atmosphere, everyone feels valued, develops teamwork skills, shows love, shares burden, teaches giving and receiving help", "Understanding family is first team we belong to", "\"Two heads are better than one\""]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,543) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-civic-education-t3-w9','ng-scheme-2025-preprimary-primary','N3','civic-education',3,'9',9,'teaching',null,'Cooperation in School','["Cooperation in school: working well in group projects, helping struggling classmates (not cheating), sharing learning materials, taking turns, following class rules together, participating in class activities, helping keep classroom clean together, cooperating with teachers, group games and sports, respecting each other, collective responsibility for class behavior, supporting classmates, school teamwork activities", "Benefits: better learning outcomes, pleasant classroom, fewer conflicts, develops social skills, achieves more together, builds friendships, makes learning fun, everyone succeeds", "Understanding \"unity is strength\"", "Cooperation is key to school success"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,543) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-civic-education-t3-w10','ng-scheme-2025-preprimary-primary','N3','civic-education',3,'10',10,'teaching',null,'Cooperation in the Community & Importance of Cooperation','["Cooperation in Community:", "How to cooperate: participating in community cleanup, helping neighbors when needed, community events and programs, youth organizations, respecting community leaders, collective security awareness, environmental care together, sharing community resources fairly, peaceful coexistence, supporting community development", "Examples: \"Age grade\" systems, community work days, collective farming (in villages), neighborhood watch Importance of Cooperation:", "Achieves goals no one can achieve alone, makes work easier and faster, builds unity and peace, develops relationships, shares skills and knowledge, multiplies success, reduces conflicts, promotes development, creates supportive environment, reflects ubuntu philosophy (\"I am because we are\"), biblical principle: \"Can two walk together except they agree?\"", "Understanding cooperation is essential for human survival and progress"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,543) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-civic-education-t3-w11','ng-scheme-2025-preprimary-primary','N3','civic-education',3,'11',11,'revision',null,'Revision of Third Term & Year''s Work','["Third Term Review:", "Orderliness (home, school, community)", "Honesty (home, school, community)", "Cooperation (home, school, community)", "Importance of all values Year-Long Comprehensive Review:", "First Term: gender equality, patriotism, national symbols, responsibilities, rights", "Second Term: specific responsibilities, good behavior (punctuality, obedience, respect, self-control)", "Third Term: orderliness, honesty, cooperation", "Complete civic values and character", "Nigerian citizenship", "Mock examination exercises"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,544) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-civic-education-t3-w12','ng-scheme-2025-preprimary-primary','N3','civic-education',3,'12',12,'examination',null,'End of Year Examination','["Third Term Assessment:", "Orderliness comprehensive test", "Honesty understanding and application", "Cooperation knowledge and practice", "Values demonstration Comprehensive Year Assessment:", "Gender and equality issues", "National identity and patriotism", "National symbols (flag, anthem, colours)", "Children''s rights and responsibilities", "Good behavior traits (punctuality, obedience, respect, self-control)", "Orderliness in all contexts", "Honesty in all settings", "Cooperation everywhere", "Overall civic education mastery", "Character and citizenship assessment", "Values integration evaluation"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,544) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-civic-education-t3-w13','ng-scheme-2025-preprimary-primary','N3','civic-education',3,'13',13,'closing',null,'Closing, Promotion & Graduation Activities','[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,545) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-physical-and-health-education-t1-w1','ng-scheme-2025-preprimary-primary','N3','physical-and-health-education',1,'1',1,'teaching',null,'Exercises and Games: Importance','["Understanding what exercise means: physical activities that make our body move and work", "Understanding what games are: organized activities with rules, usually for fun and competition", "Importance of exercises and games: keeps body strong and healthy, helps us grow properly, develops muscles and bones, improves flexibility and balance, gives us energy, helps heart and lungs work better, prevents obesity (being overweight), makes us happy and reduces stress, helps us sleep better, teaches discipline and focus, develops social skills through team games, improves coordination, builds confidence", "Understanding regular physical activity is essential for children", "Exercise should be fun, not punishment"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,546) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-physical-and-health-education-t1-w2','ng-scheme-2025-preprimary-primary','N3','physical-and-health-education',1,'2',2,'teaching',null,'Games: Basic Games','["Introduction to simple competitive games", "Egg and Spoon Race: balancing object (often bean bag or small ball) on spoon while racing, teaches balance and control, can''t let object fall", "Sack Race: jumping in sack/bag to finish line, teaches coordination and leg strength, fun competitive activity", "Blindfold and Fill a Basket: blindfolded player tries to pick up objects and put in basket (with guidance from teammates), teaches trust, listening skills, spatial awareness", "Other games: three-legged race (two people''s legs tied together), musical chairs, freeze dance, obstacle course", "Understanding rules of each game", "Fair play and sportsmanship", "Taking turns and encouraging others"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,546) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-physical-and-health-education-t1-w3','ng-scheme-2025-preprimary-primary','N3','physical-and-health-education',1,'3',3,'teaching',null,'Body Exercise: Stretching, Bending, Raising Arms and Legs, Skipping','["Stretching exercises: reaching for sky (arms up), touching toes, side stretches, neck rolls, arm circles, ankle rotations", "Importance of stretching: warms up muscles, prevents injuries, increases flexibility", "Bending exercises: bending forward, backward (carefully), side bends, knee bends (squats)", "Raising arms and legs: arm raises (front, side, up), leg raises (marching, side leg lifts, back leg lifts), developing strength and control", "Skipping: jumping with rope (forward, backward), jumping without rope, counting skips", "Benefits: improves coordination, cardiovascular fitness, leg strength", "Proper form and safety in all exercises"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,546) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-physical-and-health-education-t1-w4','ng-scheme-2025-preprimary-primary','N3','physical-and-health-education',1,'4',4,'teaching',null,'Body Exercise: Leaping and Hopping','["Leaping: big jumps from one foot to the other foot, covering distance, arm movements while leaping, leaping over small obstacles (lines, cones), leaping in different directions (forward, sideways)", "Benefits: develops leg power, improves coordination, builds confidence", "Hopping: jumping on one foot repeatedly, hopping on right foot, hopping on left foot, hopping forward and backward, hopping in place, counting hops", "Benefits: strengthens individual legs, improves balance, develops control", "Games incorporating leaping and hopping", "Understanding difference between hopping (one foot) and jumping (two feet)", "Safety: using appropriate space, not hopping on slippery surfaces"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,547) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-physical-and-health-education-t1-w5','ng-scheme-2025-preprimary-primary','N3','physical-and-health-education',1,'5',5,'midterm_assessment',null,'Mid-term Assessment/test','["Practical demonstration of exercises learned", "Stretching and bending assessment", "Leaping and hopping skills evaluation", "Participation in basic games", "Following instructions assessment", "Coordination and control observation", "Sportsmanship and fair play evaluation"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,547) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-physical-and-health-education-t1-w6','ng-scheme-2025-preprimary-primary','N3','physical-and-health-education',1,'6',6,'midterm_break',null,'Mid-term Break','[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,547) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-physical-and-health-education-t1-w7','ng-scheme-2025-preprimary-primary','N3','physical-and-health-education',1,'7',7,'teaching',null,'Body Conditioning and Balancing','["Understanding body conditioning: exercises that improve overall body fitness and control", "Understanding balance: staying steady without falling", "Standing on one leg: balancing on right leg, balancing on left leg, holding position for increasing durations, eyes open then eyes closed (more difficult), arms out for balance", "Benefits: develops balance, strengthens stabilizer muscles, improves focus and concentration", "Dancing and Freezing Game: dancing to music, freezing in position when music stops, holding freeze position (tests balance), creative movement, following rhythm", "Benefits: improves balance, develops musicality, teaches body control, enhances listening skills", "Other balancing activities: walking on line, standing on tiptoes, balance beam (low and safe)"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,547) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-physical-and-health-education-t1-w8','ng-scheme-2025-preprimary-primary','N3','physical-and-health-education',1,'8',8,'teaching',null,'Simple Movement of Parts of the Body','["Tambourine movement: moving to tambourine rhythms, fast movements when tambourine plays quickly, slow movements for slow rhythms, freezing when tambourine stops, different body parts moving to beats, coordinating movement with sound", "Basic movements: Walking (normal, fast, slow, on tiptoes, on heels, backward), Jogging (light running in place or moving), Running (faster pace, proper form - arms pumping, knees lifting), Bending (at waist, knees, various directions), Turning and spinning, Jumping, Crawling", "Understanding fundamental movement patterns", "Moving different body parts: arms, legs, head, trunk", "Coordinating movements", "Following instructions for different movements", "Moving safely in shared space"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,548) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-physical-and-health-education-t1-w9','ng-scheme-2025-preprimary-primary','N3','physical-and-health-education',1,'9',9,'teaching',null,'Manipulative Movements: Throwing and Catching','["Meaning of manipulative movements: controlling and moving objects using body parts", "Understanding manipulative skills are essential for sports", "Throwing: underhand throw, overhand throw, throwing at targets, throwing for distance, proper throwing form (step and throw), using different objects (bean bags, balls - soft)", "Catching: catching with two hands, catching balls at different heights, catching thrown bean bags, hand-eye coordination, ready position (hands out), watching the object", "Partner activities: throwing and catching with partner, gradually increasing distance, games like \"catch\"", "Safety: using soft objects, awareness of surroundings, not throwing at people''s faces"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,548) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-physical-and-health-education-t1-w10','ng-scheme-2025-preprimary-primary','N3','physical-and-health-education',1,'10',10,'teaching',null,'Neuro Muscular Skills: Dancing','["Neuro Muscular Skills:", "Meaning: coordination between nervous system (brain) and muscles to produce movement", "Dancing: moving body to music/rhythm, simple dance steps, following dance routines, creative movement, cultural dances (simple), coordination of arms and legs, rhythm and timing", "Benefits: improves coordination, develops rhythm, enhances creativity, fun exercise, cultural appreciation"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,549) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-physical-and-health-education-t1-w11','ng-scheme-2025-preprimary-primary','N3','physical-and-health-education',1,'11',11,'teaching',null,'Manipulative Movement: Somersaulting','["Somersaulting:", "Introduction to forward roll/somersault (with proper supervision and equipment)", "Safety is CRITICAL: only on proper mats, adult supervision always, proper technique taught", "Tucking chin, rolling forward smoothly, using hands for support", "Some children may not be ready - that''s okay", "Alternative: log rolls (rolling sideways)", "Building confidence gradually", "Mock practical assessment"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,549) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-physical-and-health-education-t1-w12','ng-scheme-2025-preprimary-primary','N3','physical-and-health-education',1,'12',12,'examination',null,'End of Term Examination','["Comprehensive practical examination", "Exercise demonstrations: stretching, bending, leaping, hopping", "Balance skills assessment", "Movement patterns test", "Throwing and catching evaluation", "Participation in basic games", "Dancing/rhythm coordination", "Short race participation", "Following instructions", "Overall physical fitness observation", "Sportsmanship and attitude evaluation"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,549) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-physical-and-health-education-t1-w13','ng-scheme-2025-preprimary-primary','N3','physical-and-health-education',1,'13',13,'closing',null,'Closing & End of Term Activities','["Return of assessment results", "Distribution of report cards", "Physical education achievements celebration", "Awards for athletic excellence, most improved, best sportsmanship", "Fun physical activities and games day", "Holiday exercise tips and activities", "Encouragement for active holidays", "Preview of second term activities"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,549) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-physical-and-health-education-t2-w1','ng-scheme-2025-preprimary-primary','N3','physical-and-health-education',2,'1',1,'teaching',null,'Development Through Sport Activities: Physical Development','["Understanding how sports and physical activities help our bodies develop", "Elements of physical development through sports:", "Flexibility: ability to bend and stretch easily, improved through stretching exercises", "Agility: ability to move quickly and change directions easily, developed through games and drills", "Balance: staying steady without falling, improved through balance exercises", "Coordination: using different body parts together smoothly, developed through various activities", "Reaction: responding quickly to signals/situations, improved through games", "Speed: how fast we move, developed through running activities", "Strength: how strong muscles are, developed through exercise", "Understanding regular sports/exercise develops all these elements", "Age-appropriate development expectations"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,551) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-physical-and-health-education-t2-w2','ng-scheme-2025-preprimary-primary','N3','physical-and-health-education',2,'2',2,'teaching',null,'Development Through Sport Activities: Emotional Development','["Understanding sports and games affect how we feel (emotions)", "Elements of emotional development through sports:", "Positive emotions: Zeal/enthusiasm (eagerness to play and try), Excitement (happiness about activity), Contentment (satisfaction with participation), Joy (happiness from playing), Confidence (believing in abilities), Pride (in achievements)", "Negative emotions (and how to manage): Anxiety (nervousness - overcome through practice), Apathy (lack of interest - find enjoyable activities), Anger (frustration - learn self-control), Boredom (not interested - try variety), Hostility (aggression - learn peaceful competition), Disappointment (when losing - learn good sportsmanship)", "Learning to manage emotions through sports", "Understanding winning and losing are both part of games", "Building emotional resilience through physical activities"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,551) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-physical-and-health-education-t2-w3','ng-scheme-2025-preprimary-primary','N3','physical-and-health-education',2,'3',3,'teaching',null,'Development Through Sport Activities: Social Development','["Understanding sports help us learn to interact with others", "Elements of social development through sports:", "Cooperation: working together with team members, helping each other", "Teamwork: playing together toward common goal, understanding everyone''s role", "Tolerance: accepting others'' mistakes, being patient with different skill levels", "Friendliness: being kind to teammates and opponents, making friends through sports", "Fairness: playing by rules, not cheating, accepting referee decisions", "Hospitality: welcoming new players, being inclusive", "Respect: for coaches, opponents, teammates, equipment, rules", "Communication: talking to teammates, listening to instructions", "Leadership: sometimes leading, sometimes following", "Understanding sports teach life skills", "Building character through physical education"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,552) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-physical-and-health-education-t2-w4','ng-scheme-2025-preprimary-primary','N3','physical-and-health-education',2,'4',4,'teaching',null,'Marching Exercise: Concept and Importance','["Concept of marching exercise: organized walking in rhythm and pattern, often in formation", "Understanding marching combines physical activity with discipline", "Basic marching skills: standing at attention (straight posture, arms at sides), marching in place (lifting knees, coordinated arms), marching forward (in time with others), turning while marching (left, right, about-face), starting and stopping on command, maintaining proper spacing, swinging arms rhythmically", "Marching commands: \"Attention,\" \"Forward march,\" \"Halt,\" \"Left turn,\" \"Right turn\"", "Importance of marching: develops discipline and focus, improves coordination, teaches following instructions, builds teamwork (moving together), develops good posture, prepares for organized activities/events, enhances listening skills, cultural significance (military, parades, ceremonies)", "Simple marching drills and practice"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,552) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-physical-and-health-education-t2-w5','ng-scheme-2025-preprimary-primary','N3','physical-and-health-education',2,'5',5,'midterm_assessment',null,'Mid-term Assessment/test','["Physical, emotional, and social development understanding test", "Marching skills practical assessment", "Following marching commands", "Coordination and discipline evaluation", "Teamwork observation", "Attitude and behavior in sports assessment"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,553) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-physical-and-health-education-t2-w6','ng-scheme-2025-preprimary-primary','N3','physical-and-health-education',2,'6',6,'midterm_break',null,'Mid-term Break','[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,553) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-physical-and-health-education-t2-w7','ng-scheme-2025-preprimary-primary','N3','physical-and-health-education',2,'7',7,'teaching',null,'Body Exercise: Swinging and Twisting','["Swinging exercises: Arm swings (forward and backward, side to side, circles), Leg swings (forward and back, side to side - holding support), Combined arm swings (both arms together, alternate arms), Trunk swinging (gentle swinging from waist)", "Benefits: loosens joints, improves flexibility, warms up muscles, develops rhythm", "Twisting exercises: Trunk twists (left and right, hands on waist or arms extended), Hip twists, Neck turns (gentle), Ankle and wrist rotations, Full body twist", "Benefits: improves flexibility, strengthens core muscles, enhances range of motion", "Safety: movements should be controlled, not jerky, warm up before twisting exercises", "Combining swinging and twisting in routines"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,553) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-physical-and-health-education-t2-w8','ng-scheme-2025-preprimary-primary','N3','physical-and-health-education',2,'8',8,'teaching',null,'Body Exercise: Jumping and Bending','["Jumping exercises: Jumping with two feet together, Jumping jacks (arms and legs out and in), Jump and turn (90°, 180°), Jumping forward and backward, Jumping side to side, Jumping over small objects, Jumping in patterns, High jumps (reaching up), Long jumps (forward distance)", "Benefits: strengthens legs, improves cardiovascular fitness, develops power, enhances coordination", "Bending exercises review: Forward bends (touching toes), Backward bends (careful, supervised), Side bends (left and right), Knee bends (squats), Combined bending (incorporating arms)", "Benefits: increases flexibility, strengthens muscles, improves posture", "Proper technique and safety in all movements"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,553) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-physical-and-health-education-t2-w9','ng-scheme-2025-preprimary-primary','N3','physical-and-health-education',2,'9',9,'teaching',null,'Neuro Muscular Skills: Climbing','["Meaning of neuromuscular skills review: brain and muscles working together", "Climbing: developing coordination and strength through climbing activities", "Types of climbing (age-appropriate and supervised): Climbing playground equipment (slides, jungle gyms), Climbing stairs (various ways - forward, sideways, backward carefully), Climbing ladders (supervised), Climbing over obstacles (mats, benches - low height), Wall climbing (if available, with proper equipment)", "Skills involved: hand-eye coordination, foot placement, body awareness, strength (arms, legs, core), problem-solving (planning route), confidence and courage", "Benefits: full-body workout, develops strength, improves coordination, builds confidence, spatial awareness", "Safety: proper supervision always, appropriate equipment, safe heights for age, teaching proper technique, spotting children, safe landing surfaces"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,554) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-physical-and-health-education-t2-w10','ng-scheme-2025-preprimary-primary','N3','physical-and-health-education',2,'10',10,'teaching',null,'Track Events','["Track Events:", "Introduction to track events: running races on designated path/track", "Short distance race (25m race): understanding race distance (about 25 meters), starting position (standing or crouching), listening for start signal, running straight to finish line, not stopping until past finish, proper running form", "Race rules and sportsmanship", "Celebrating all participants, not just winners", "Running in pairs: understanding partner racing, coordinating with partner, staying together (or tied together in some formats), communication while running, teamwork in racing", "Benefits: develops cooperation, adds challenge, teaches coordination with others"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,554) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-physical-and-health-education-t2-w11','ng-scheme-2025-preprimary-primary','N3','physical-and-health-education',2,'11',11,'teaching',null,'Posture','["Posture:", "Meaning of posture: position in which we hold our body", "Good sitting posture: back straight, feet flat on floor, sitting back in chair, not slouching, head level, shoulders relaxed", "Importance: prevents back pain, better breathing, easier concentration, looks confident", "Good standing posture: standing straight, shoulders back, head up, weight distributed evenly on both feet, stomach in, not leaning to one side", "Importance: prevents fatigue, looks confident, better for spine health, proper body alignment", "Good reading posture: book at proper distance (not too close), adequate lighting, sitting with back support, book at eye level, not lying flat while reading, taking breaks", "Importance: prevents eye strain, better reading, prevents neck pain", "Good sleeping posture: sleeping on side (best) or back, proper pillow height, comfortable mattress, not sleeping on stomach (can strain neck), relaxed position", "Importance: better sleep quality, prevents body aches, proper spine alignment, waking refreshed", "Mock examination activities"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,554) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-physical-and-health-education-t2-w12','ng-scheme-2025-preprimary-primary','N3','physical-and-health-education',2,'12',12,'examination',null,'End of Term Examination','["Comprehensive physical activities assessment", "Marching skills test", "Body exercises demonstration (swinging, twisting, jumping, bending)", "Climbing skills evaluation (if equipment available)", "Running activities assessment", "Posture demonstration (sitting, standing, reading)", "Understanding of development through sports", "Teamwork and social skills observation", "Overall fitness and coordination evaluation"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,555) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-physical-and-health-education-t2-w13','ng-scheme-2025-preprimary-primary','N3','physical-and-health-education',2,'13',13,'closing',null,'Closing & End of Term Activities','["Return of assessment results", "Distribution of report cards", "Physical fitness celebration", "Awards for excellence and improvement", "Fun sports day activities", "Holiday fitness tips", "Preview of third term (indoor games, ball games, specific sports)", "End of term celebrations"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,555) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-physical-and-health-education-t3-w1','ng-scheme-2025-preprimary-primary','N3','physical-and-health-education',3,'1',1,'teaching',null,'Indoor Games','["Understanding indoor games: games played inside buildings, don''t require large spaces", "Why indoor games are important: can play when weather is bad, develops mental skills, different from outdoor sports, quieter activities", "Examples of indoor games:", "Chess (introduction - will be covered in detail later)", "Ludo game: board game with dice, moving pieces around board, reaching home first", "Card games: simple matching games, memory games, uno", "Video games (introduction - will be covered in detail later)", "Other indoor games: checkers/draughts, dominoes, puzzles, board games (Snakes and Ladders, Monopoly Jr.), table games", "Benefits: develops thinking skills, patience, strategy, following rules, taking turns", "Understanding balance between indoor and outdoor activities"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,557) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-physical-and-health-education-t3-w2','ng-scheme-2025-preprimary-primary','N3','physical-and-health-education',3,'2',2,'teaching',null,'Sport Facilities and Equipment','["Meaning of sport facilities: places and structures where sports are played", "Examples of sport facilities: field/playground (for running, football, games), gym/gymnasium (indoor sports facility), swimming pool, basketball court, volleyball court, tennis court, track (for races)", "Meaning of sport equipment: tools and items used to play sports", "Examples of sport equipment: balls (football, basketball, tennis, etc.), stopwatch (timing races), whistle (referee''s tool), bibs/vests (identifying teams), boots/cleats (for football, other sports), shin guards (protection), goalposts, nets, bats/rackets, cones (marking areas), ropes, mats", "Importance of facilities and equipment: make sports possible, ensure safety, enhance performance, organize activities", "Taking care of sport equipment: using properly, storing safely, not damaging, reporting broken items", "Understanding not all schools have all facilities - making do with available resources"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,557) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-physical-and-health-education-t3-w3','ng-scheme-2025-preprimary-primary','N3','physical-and-health-education',3,'3',3,'teaching',null,'Ball Games and Exercises: Football (Part 1)','["Understanding football/soccer: most popular sport worldwide, played with round ball, two teams trying to score goals", "Basic football skills:", "Passing: kicking ball to teammate, inside of foot pass (most accurate), outside of foot pass, different power passes", "Dribbling: moving ball forward while maintaining control, using both feet, keeping ball close, looking up while dribbling", "Shooting: kicking ball toward goal to score, power and accuracy, different shooting techniques", "Introduction to other skills: stopping/controlling ball, basic defending", "Football equipment: ball (size 3 for young children), jersey/shirt, shorts, socks, boots/cleats (or trainers), shin guards, whistle (for referee), goalposts", "Basic rules (simplified): no hands (except goalkeeper), score by putting ball in goal, offside (very basic concept), fouls and free kicks", "Benefits: teamwork, cardiovascular fitness, coordination, strategic thinking"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,558) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-physical-and-health-education-t3-w4','ng-scheme-2025-preprimary-primary','N3','physical-and-health-education',3,'4',4,'teaching',null,'Ball Games and Exercises: Football (Part 2) & Basketball','["Football continued:", "Practice and games", "Simple football drills", "Mini football matches", "Positions (very basic): goalkeeper, defenders, midfielders, forwards", "Sportsmanship in football Basketball:", "Introduction to basketball: played with orange ball, two teams, scoring by throwing ball through elevated hoop/basket", "Basic basketball skills:", "Bouncing/Dribbling: bouncing ball continuously while moving, using fingertips not palm, alternating hands, keeping ball low, looking up", "Throwing/Passing: chest pass (two hands from chest), bounce pass (ball bounces to teammate), overhead pass", "Shooting: throwing ball toward basket to score, proper form (BEEF", "Balance, Eyes, Elbow, Follow-through - simplified)", "Basketball equipment: basketball (size 5 for children), hoops/baskets (lowered for children), jersey, shorts, basketball shoes/boots, whistle", "Basic rules (simplified): dribble or pass (no running with ball), score in opponent''s basket, no pushing/holding", "Benefits: height development, jumping ability, hand-eye coordination, teamwork"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,558) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-physical-and-health-education-t3-w5','ng-scheme-2025-preprimary-primary','N3','physical-and-health-education',3,'5',5,'midterm_assessment',null,'Mid-term Assessment/test','["Indoor games knowledge test", "Sport facilities and equipment identification", "Football skills practical assessment", "Basketball skills evaluation", "Dribbling, passing, shooting tests", "Game participation and teamwork", "Sportsmanship observation"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,559) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-physical-and-health-education-t3-w6','ng-scheme-2025-preprimary-primary','N3','physical-and-health-education',3,'6',6,'midterm_break',null,'Mid-term Break','[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,559) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-physical-and-health-education-t3-w7','ng-scheme-2025-preprimary-primary','N3','physical-and-health-education',3,'7',7,'teaching',null,'Table Tennis','["Concept of table tennis (ping-pong): indoor racket sport, played on table with net, small ball, two or four players", "Understanding it''s called \"table tennis\" because it''s like tennis but on table", "Basic skills in table tennis:", "Gripping: holding bat/paddle properly (shake-hand grip or pen-hold grip - simple version)", "Serving: starting play by hitting ball so it bounces on own side then opponent''s side, underhand serve", "Stroking: hitting ball back and forth, forehand stroke (hitting on same side as grip), backhand stroke (hitting across body)", "Returning: hitting ball back to opponent, proper positioning", "Equipment needed: table tennis table (with net), ball (small, light, white or orange), bats/paddles/rackets (two), sometimes score board", "Basic rules (simplified): serve must bounce on both sides, ball bounces once only, alternating serves, scoring (simple point system)", "Benefits: improves reflexes, hand-eye coordination, concentration, quick thinking", "Can be played indoors in any weather"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,559) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-physical-and-health-education-t3-w8','ng-scheme-2025-preprimary-primary','N3','physical-and-health-education',3,'8',8,'teaching',null,'Chess','["Concept of chess: strategy board game, two players, different pieces with different moves, goal is to checkmate opponent''s king", "Understanding chess is a thinking game, not a physical game", "Chess board: 64 squares (8x8), alternating light and dark colors", "Chess pieces (introduction - very basic for nursery level): King (most important), Queen (powerful), Rook/Castle, Bishop, Knight, Pawns", "Very basic introduction to how some pieces move (detailed learning comes later in primary school)", "Understanding chess teaches: thinking ahead, planning, patience, concentration, problem-solving, decision-making", "Benefits: develops intelligence, improves memory, teaches cause and effect, enhances creativity, improves focus", "Understanding chess is popular worldwide", "Famous chess players (brief mention)", "Beginning chess: setting up board, identifying pieces", "Note: Full chess rules typically taught in Primary school, this is just introduction"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,560) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-physical-and-health-education-t3-w9','ng-scheme-2025-preprimary-primary','N3','physical-and-health-education',3,'9',9,'teaching',null,'Video Games','["Meaning of video games: games played on electronic devices (computers, tablets, game consoles, phones)", "Understanding video games are indoor entertainment", "Examples of video games (age-appropriate):", "Solitaire: card game on computer", "Super Mario: adventure game with character Mario", "Soccer games (PES/FIFA): football simulation games", "Temple Run: running and obstacle avoidance game", "Educational games: math games, spelling games, learning games", "Other mentions: Grand Theft Auto (note: this is NOT age-appropriate for nursery - should clarify), Brick breaker, Puzzle games", "Understanding moderation: video games can be fun but shouldn''t replace physical activity, screen time limits, importance of outdoor play, balancing video games with other activities", "Benefits when used properly: hand-eye coordination, problem-solving, strategic thinking, entertainment", "Concerns: too much screen time, reduced physical activity, eye strain", "Rules for video game use: ask parents first, play age-appropriate games only, take breaks, limit time"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,560) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-physical-and-health-education-t3-w10','ng-scheme-2025-preprimary-primary','N3','physical-and-health-education',3,'10',10,'teaching',null,'Review of All Ball Games and Indoor Activities','["Comprehensive review of football: skills, rules, equipment", "Basketball review: skills, rules, equipment", "Table tennis review: skills, equipment", "Chess introduction review", "Indoor games comprehensive review", "Video games discussion and understanding moderation", "Sport facilities and equipment review", "Comparing different sports: similarities and differences", "Understanding variety in sports and games", "Choosing sports based on interest and ability", "Practice sessions for all activities covered"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,561) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-physical-and-health-education-t3-w11','ng-scheme-2025-preprimary-primary','N3','physical-and-health-education',3,'11',11,'revision',null,'Revision of Third Term & Year''s Work','["Third Term Review:", "Indoor games comprehensive practice", "Sport facilities and equipment", "Ball games skills (football, basketball, table tennis)", "Chess basics", "Video games understanding and moderation Year-Long Comprehensive Review:", "First Term: basic exercises, games, body movements, manipulative movements, track events", "Second Term: development through sports, marching, body exercises, neuromuscular skills, posture", "Third Term: indoor games, sport facilities, ball games", "Complete physical and health education review", "All physical skills practice", "Understanding healthy active lifestyle", "Mock comprehensive examination"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,561) on conflict (id) do nothing;
