insert into curriculum_topics values ('N3-personal-development-t1-w7','ng-scheme-2025-preprimary-primary','N3','personal-development',1,'7',7,'teaching',null,'Correct Learning Position','["Correct Learning Position:", "Proper sitting position: back straight, feet on floor, facing forward", "Sitting at appropriate distance from desk", "Position for different activities: sitting for writing, sitting on mat for story time, standing for songs", "Not rocking on chair or standing unnecessarily", "Importance: better learning, good posture, safety"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,576) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-personal-development-t1-w8','ng-scheme-2025-preprimary-primary','N3','personal-development',1,'8',8,'teaching',null,'Proper Way of Answering Questions','["Raising hand and waiting to be called before answering", "Not shouting out answers", "Speaking clearly and loudly enough to be heard", "Standing when answering (if required by teacher)", "Looking at teacher when answering", "Thinking before answering", "It''s okay to say \"I don''t know\" and asking for help", "Not interrupting when others are answering", "Respecting others'' attempts to answer", "Understanding mistakes are part of learning", "Encouraging others when they answer", "Being confident when speaking"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,576) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-personal-development-t1-w9','ng-scheme-2025-preprimary-primary','N3','personal-development',1,'9',9,'teaching',null,'Proper Way to Sneeze, Yawn and Cough','["Sneezing: covering nose and mouth with tissue or elbow (not hands), turning head away from people, disposing tissue properly, washing hands after, saying \"excuse me\"", "Yawning: covering mouth with hand or turning away, trying to yawn quietly, saying \"excuse me,\" understanding yawning is natural when tired", "Coughing: covering mouth with tissue or elbow, turning away from people, not coughing on food or others, washing hands, saying \"excuse me,\" telling adults if cough persists", "Understanding these actions spread germs if not done properly", "Hygiene and consideration for others", "Importance of tissues and handkerchiefs", "Washing hands frequently"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,576) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-personal-development-t1-w10','ng-scheme-2025-preprimary-primary','N3','personal-development',1,'10',10,'teaching',null,'Orderliness, Bullying and Fighting','["Orderliness:", "Meaning: keeping things organized and tidy", "Keeping desk and belongings organized", "Lining up properly", "Following routines and schedules", "Putting things in proper places", "Doing things in proper sequence", "Benefits: easy to find things, shows discipline, creates pleasant environment Bullying and Fighting:", "Understanding bullying: repeatedly hurting others (words or actions)", "Bullying and fighting are bad and wrong", "Effects: hurt feelings, fear, injuries", "What to do if bullied: tell teacher/parent, walk away, say \"stop\"", "Not bullying others", "Using words instead of fighting", "Being kind to everyone", "Reporting problems to adults"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,577) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-personal-development-t1-w11','ng-scheme-2025-preprimary-primary','N3','personal-development',1,'11',11,'teaching',null,'Proper Use of Materials','["Proper Use of Materials:", "Handling books carefully (not tearing, not bending pages)", "Using pencils, crayons, scissors correctly and safely", "Sharing materials with classmates", "Returning materials to proper places", "Not wasting materials", "Asking permission before using others'' materials", "Taking care of school property", "Being responsible with learning tools"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,577) on conflict (id) do nothing;
