insert into curriculum_topics values ('N3-personal-development-t2-w1','ng-scheme-2025-preprimary-primary','N3','personal-development',2,'1',1,'teaching',null,'Greetings in the Morning and Afternoon','["Importance of greetings: shows respect, friendliness, good manners", "Morning greetings: \"Good morning\" (to everyone), \"Good morning, Ma/Sir\" (to teachers), \"Good morning, Mummy/Daddy\" (to parents), time for morning greetings (from waking until 12 noon)", "Afternoon greetings: \"Good afternoon\" (to everyone), \"Good afternoon, Ma/Sir\" (to teachers), time for afternoon greetings (from 12 noon until evening)", "Evening greetings: \"Good evening\" (from around 4-5pm onward)", "Proper tone and body language when greeting", "Responding to greetings appropriately", "Greeting everyone: adults, peers, visitors", "Cultural greetings in local languages", "Understanding greeting makes people feel valued"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,579) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-personal-development-t2-w2','ng-scheme-2025-preprimary-primary','N3','personal-development',2,'2',2,'teaching',null,'Congratulatory Greetings','["Congratulatory Greetings:", "Understanding congratulations: expressing happiness for someone''s achievement", "When to congratulate: birthdays (\"Happy Birthday\"), passing exams (\"Congratulations,\" \"Well done\"), winning competitions, achievements, promotions, weddings, new babies", "How to congratulate: saying congratulatory words, clapping, giving cards/gifts, smiling, showing genuine happiness", "Being happy for others'' success"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,579) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-personal-development-t2-w3','ng-scheme-2025-preprimary-primary','N3','personal-development',2,'3',3,'teaching',null,'Avoiding Bad Influence & Making Friends with Good People','["Avoiding Bad Influence:", "Understanding influence: effect people have on our behavior", "Bad influence: people who encourage wrong behavior (lying, stealing, fighting, disobedience, rudeness)", "Recognizing bad influence: if someone makes you do wrong things", "How to avoid: saying \"no\" to wrong things, walking away, choosing good friends, telling parents/teachers", "Understanding peer pressure", "Making own good decisions Making Friends with Good People:", "Good people: kind, honest, respectful, obedient, helpful", "Benefits of good friends: become better person, stay out of trouble, happiness", "How to choose friends: look for good character, shared positive interests", "Being a good friend yourself: kind, honest, loyal, helpful", "Understanding \"show me your friend and I''ll tell you who you are\""]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,579) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-personal-development-t2-w4','ng-scheme-2025-preprimary-primary','N3','personal-development',2,'4',4,'teaching',null,'Simple Courtesy: "Excuse Me Please"','["Simple Courtesy", "\"Excuse Me Please\":", "When to use \"Excuse me\": getting someone''s attention, passing through a crowd, interrupting politely, leaving table, getting past someone, before asking question, after burping/sneezing", "Understanding it''s polite way to get attention", "Tone: saying it politely, not demanding", "Waiting after saying it", "Adding \"please\" makes it more polite"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,580) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-personal-development-t2-w5','ng-scheme-2025-preprimary-primary','N3','personal-development',2,'5',5,'midterm_assessment',null,'Mid-term Assessment/test','["Greetings at different times test", "Congratulatory and sympathy expressions", "Friendship and influence understanding", "Courtesy expressions usage", "School rules knowledge test", "Practical courtesy demonstrations"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,580) on conflict (id) do nothing;
