insert into curriculum_topics values ('N3-personal-development-t2-w7','ng-scheme-2025-preprimary-primary','N3','personal-development',2,'7',7,'teaching',null,'Proper Ways of Answering Your Name','["Importance of responding when name is called", "Proper responses: \"Yes, Ma/Sir,\" \"Present,\" \"Here\"", "Speaking clearly and audibly", "Looking at person who called your name", "Responding promptly (not ignoring)", "Standing if required by teacher", "Not shouting response", "Understanding answering name shows respect and attention", "Being alert and attentive during roll call", "Practice sessions for name-calling", "Cultural variations in responses", "Understanding your name is important and personal"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,580) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-personal-development-t2-w8','ng-scheme-2025-preprimary-primary','N3','personal-development',2,'8',8,'teaching',null,'Simple Courtesy: Greeting with Appropriate Courtesy','["Review of greetings from earlier weeks", "Cultural context of greetings in Nigeria", "Traditional greetings: kneeling/prostrating for elders (depending on culture), shaking hands appropriately, bowing slightly", "Modern greetings: handshake, verbal greetings", "Age-appropriate greetings: to elders (more formal and respectful), to peers (friendly), to younger ones (kind)", "Body language: smiling, eye contact (where culturally appropriate), pleasant expression", "Time-appropriate greetings review", "Special greetings: \"Welcome,\" \"How are you?\" and appropriate responses", "Greeting visitors to school/home", "Understanding greeting customs may vary by culture", "Showing respect through proper greetings"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,581) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-personal-development-t2-w9','ng-scheme-2025-preprimary-primary','N3','personal-development',2,'9',9,'teaching',null,'Simple Courtesy: Saying "Thank You"','["Understanding gratitude: being thankful and appreciating others", "When to say \"Thank you\": receiving gifts, receiving help, after meals (to cook/parents), when served, receiving compliments, when someone does something for you, after borrowing and returning", "How to say it: sincerely, looking at person, with smile, clearly", "Other expressions of thanks: \"Thanks,\" \"Thank you very much,\" \"I appreciate it\"", "Responding to \"Thank you\": \"You''re welcome,\" \"It''s my pleasure,\" \"No problem\"", "Writing thank you notes (simple)", "Understanding gratitude makes others feel valued", "Being genuinely thankful", "Not taking things for granted"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,581) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-personal-development-t2-w10','ng-scheme-2025-preprimary-primary','N3','personal-development',2,'10',10,'teaching',null,'Simple Courtesy: Saying "I Am Sorry" & "Pardon Me"','["\"I Am Sorry\":", "Understanding apology: saying sorry for mistakes or wrongs", "When to apologize: hurting someone (physically or emotionally), breaking things, making mistakes, being late, disobeying, lying", "How to apologize: sincerely, looking at person, meaning it, not making excuses, promising to do better", "Accepting apologies: forgiving, saying \"It''s okay,\" \"I forgive you\"", "Understanding apologizing shows good character", "Making amends after apologizing \"Pardon Me\":", "Similar to \"Excuse me\" but slightly different", "When to use: didn''t hear someone (asking them to repeat), made small mistake, need to interrupt, before disagreeing politely", "Understanding it''s polite expression", "Tone and manner of saying it"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,581) on conflict (id) do nothing;
