insert into curriculum_topics values ('N3-personal-development-t3-w1','ng-scheme-2025-preprimary-primary','N3','personal-development',3,'1',1,'teaching',null,'Making Request Politely: "Could You Kindly..."','["Understanding polite requests: asking for things in respectful way", "Polite request phrases: \"Could you kindly...,\" \"May I please...,\" \"Would you mind...,\" \"Can I please...,\" \"Please could you...\"", "When to make requests: needing help, wanting something, asking permission, requesting service", "How to make polite requests: using magic words (please, kindly), proper tone (not demanding), clear speech, patient waiting for response, accepting \"no\" gracefully", "Difference between demanding and requesting", "Examples: \"Could you kindly help me?\" \"May I please have...?\" \"Would you mind opening...?\"", "Understanding polite requests more likely to be granted", "Thanking person after request is granted", "Building respectful communication skills"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,583) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-personal-development-t3-w2','ng-scheme-2025-preprimary-primary','N3','personal-development',3,'2',2,'teaching',null,'Etiquette: Minding Your Language Always','["Understanding etiquette: good manners and proper behavior", "Minding language: watching what we say and how we say it", "Using appropriate words: no bad words, no insults, no name-calling, no cursing", "Speaking respectfully to everyone: elders, peers, younger ones", "Tone of voice: not shouting, not being rude, speaking kindly", "When to speak and when to be quiet: not interrupting, not talking during serious moments, being quiet in certain places", "Positive language: encouraging words, kind comments, compliments", "Avoiding gossip and tale-bearing", "Understanding words can hurt or heal", "\"Think before you speak\"", "Consequences of bad language: punishment, hurt feelings, bad reputation"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,583) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-personal-development-t3-w3','ng-scheme-2025-preprimary-primary','N3','personal-development',3,'3',3,'teaching',null,'Etiquette: Minding Your Dressing','["Understanding dressing reflects who we are", "Appropriate dressing for different occasions: school (uniform), home (casual but decent), church/mosque (modest and respectful), parties (neat and appropriate), sports (sportswear)", "School uniform: wearing complete uniform, properly worn (tucked in, buttoned), clean and neat, correct shoes and socks", "Cleanliness: wearing clean clothes daily, bathing before dressing, clean shoes", "Modesty: covering body appropriately, age-appropriate clothing", "Neatness: clothes well-ironed, no torn clothes, matching clothes", "Cultural considerations in dressing", "Understanding dressing shows respect for self and others", "Not judging others by their clothes", "Pride in appearance without vanity"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,583) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-personal-development-t3-w4','ng-scheme-2025-preprimary-primary','N3','personal-development',3,'4',4,'teaching',null,'School Etiquette: How to Behave Politely in School','["Understanding school etiquette: proper behavior expected in school", "In classroom: raising hand before speaking, not talking when teacher is teaching, paying attention, respecting classmates, keeping area clean, not eating during lessons (unless allowed)", "In assembly: standing straight, being quiet, singing along, paying attention", "In corridors: walking (not running), speaking quietly, giving way to others, not pushing", "In dining area: queuing properly, table manners, not wasting food, cleaning up after eating", "In playground: playing safely, sharing equipment, including others, following game rules", "In library: being very quiet, handling books carefully, not running", "In toilets: using properly, keeping clean, washing hands, not playing", "General school etiquette: greeting all staff, respecting school property, following all school rules, being helpful", "Representing school well always"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,584) on conflict (id) do nothing;
