insert into curriculum_topics values ('N3-personal-development-t3-w7','ng-scheme-2025-preprimary-primary','N3','personal-development',3,'7',7,'teaching',null,'Etiquette in Public Places: Church/mosque','["Understanding public places: places used by many people", "Church etiquette: arriving on time, dressing modestly and respectfully, being quiet and attentive, not playing or running, singing along, sitting properly, not eating or chewing gum, turning off phones (for adults), greeting people politely, respecting sacred space, following church rules, listening to sermon/teaching", "Mosque etiquette: removing shoes before entering, performing ablution if required, dressing modestly (covering appropriately), being quiet, men and women in separate areas (understanding), sitting properly, listening to Imam, not walking in front of those praying, respecting prayer times", "Understanding religious places are sacred", "Respecting all religions even if different from yours", "General reverence and respect in worship places"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,585) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-personal-development-t3-w8','ng-scheme-2025-preprimary-primary','N3','personal-development',3,'8',8,'teaching',null,'Etiquette in Public Places: Museum and Other Public Facilities','["Museum etiquette: speaking quietly or whispering, not touching exhibits (unless \"please touch\" sign), following guide''s instructions, walking carefully, no running, taking pictures only if allowed, learning and asking questions appropriately, not eating or drinking, respecting artifacts and displays", "Library etiquette: complete silence or very quiet whispers, handling books carefully, returning books to proper places, not running, asking librarian for help quietly", "Hospital/Clinic etiquette: being quiet (people are sick), sitting patiently, following nurses'' instructions, not touching medical equipment, showing sympathy to sick people", "Park etiquette: not littering, not destroying plants or equipment, sharing play equipment, playing safely", "Shopping mall/market etiquette: staying with adults, not touching everything, queuing properly, being polite to shopkeepers", "Public transport etiquette: giving seats to elderly/pregnant women, queuing properly, not being too loud", "General public behavior: being respectful, following rules, considering others"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,585) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-personal-development-t3-w9','ng-scheme-2025-preprimary-primary','N3','personal-development',3,'9',9,'teaching',null,'How to Show Sympathy','["Understanding sympathy: showing care when someone is sad or has problems", "When to show sympathy: sickness, loss, sadness, accidents, disappointment", "How to show sympathy: saying \"I''m sorry,\" \"I hope you feel better,\" comforting words, being gentle, not laughing at their problem, offering help, listening", "Understanding sympathy shows kindness and empathy"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,586) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-personal-development-t3-w10','ng-scheme-2025-preprimary-primary','N3','personal-development',3,'10',10,'teaching',null,'School Rules and Regulations','["Understanding rules: guidelines for behavior", "Why schools have rules: safety, order, fairness, better learning", "Common school rules: arriving on time, wearing uniform, obeying teachers, no fighting, no bullying, staying in designated areas, respecting property, completing work", "Consequences of breaking rules: punishment, loss of privileges", "Benefits of following rules: safe environment, good learning, good reputation", "Respecting and obeying school rules"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,586) on conflict (id) do nothing;
