insert into curriculum_topics values ('N3-songs-and-rhymes-t1-w1','ng-scheme-2025-preprimary-primary','N3','songs-and-rhymes',1,'1',1,'teaching',null,'This Little Pig','["Learning the traditional finger rhyme", "Five verses for five toes/fingers: \"This little pig went to market,\" \"This little pig stayed home,\" \"This little pig had roast beef,\" \"This little pig had none,\" \"This little pig cried ''Wee, wee, wee'' all the way home\"", "Touching each toe/finger with each verse", "Understanding the story sequence", "Actions: gentle tickling on last verse", "Counting practice (five pigs)", "Parent-child bonding activity", "Fun and interactive performance"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,587) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-songs-and-rhymes-t1-w2','ng-scheme-2025-preprimary-primary','N3','songs-and-rhymes',1,'2',2,'teaching',null,'Old Macdonald Had a Farm','["Learning the classic farm song", "Understanding farm animals and their sounds", "Animal sounds: cow (moo), pig (oink), duck (quack), sheep (baa), horse (neigh), chicken (cluck), dog (woof), cat (meow)", "Repetitive chorus: \"E-I-E-I-O\"", "Verse structure with animal names", "Acting out different animals", "Making appropriate animal sounds", "Taking turns choosing which animal to sing about", "Understanding farm life and animals"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,587) on conflict (id) do nothing;
insert into curriculum_topics values ('N3-songs-and-rhymes-t1-w3','ng-scheme-2025-preprimary-primary','N3','songs-and-rhymes',1,'3',3,'teaching',null,'Jack and Jill Went Up the Hill','["Learning the traditional nursery rhyme", "Story: Jack and Jill going up hill to fetch water, Jack falling and tumbling, Jill tumbling after", "Understanding the narrative", "Rhyming words: hill/Jill, crown/down, after/laughter", "Actions: pretending to climb, falling down safely, tumbling", "Discussing helping each other", "Simple melody", "Traditional rhyme appreciation", "Group performance"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,587) on conflict (id) do nothing;
