insert into curriculum_topics values ('P1-social-and-citizenship-studies-t2-w1','ng-scheme-2025-preprimary-primary','P1','social-and-citizenship-studies',2,'1',1,'teaching',null,'People, Places and Objects to Respect (Part 1)','["Respecting elders: parents, grandparents, teachers, community leaders", "How to show respect: greeting properly, listening, obeying, using respectful titles", "Respecting people of all ages and backgrounds", "Treating everyone with kindness", "Why respect is important in society"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,656) on conflict (id) do nothing;
insert into curriculum_topics values ('P1-social-and-citizenship-studies-t2-w2','ng-scheme-2025-preprimary-primary','P1','social-and-citizenship-studies',2,'2',2,'teaching',null,'People, Places and Objects to Respect (Part 2)','["Sacred places: churches, mosques, shrines, traditional sites", "Respecting religious places: quiet behavior, proper dressing, no littering", "Respecting national monuments and symbols", "Objects to respect: flags, religious books, elders'' belongings", "Public places: schools, hospitals, government buildings - how to behave"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,656) on conflict (id) do nothing;
insert into curriculum_topics values ('P1-social-and-citizenship-studies-t2-w3','ng-scheme-2025-preprimary-primary','P1','social-and-citizenship-studies',2,'3',3,'teaching',null,'Marriage','["Understanding what marriage is (when a man and woman become husband and wife)", "Marriage creates families", "Different types of marriage ceremonies: traditional, religious (church/mosque), court", "Roles in marriage: husband and wife work together, love and respect each other", "Children come from married parents (family structure)"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,656) on conflict (id) do nothing;
insert into curriculum_topics values ('P1-social-and-citizenship-studies-t2-w4','ng-scheme-2025-preprimary-primary','P1','social-and-citizenship-studies',2,'4',4,'teaching',null,'Responsible Parenting','["Understanding parenting (taking care of children)", "Responsibilities of parents: feeding, clothing, educating, loving children", "What makes a good parent: caring, patient, provides for needs, teaches right from wrong", "Children should obey and respect their parents", "Appreciation for parents'' efforts"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,656) on conflict (id) do nothing;
