insert into curriculum_topics values ('P1-social-and-citizenship-studies-t2-w7','ng-scheme-2025-preprimary-primary','P1','social-and-citizenship-studies',2,'7',7,'teaching',null,'Roles of Members of the Family','["Father''s role: provides for family, protects, guides children", "Mother''s role: cares for children, cooks, manages home, teaches children", "Children''s role: obey parents, help with chores, study hard, respect siblings", "Grandparents'' role: wisdom, advice, storytelling, cultural knowledge", "Extended family members: uncles, aunts, cousins - support system"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,656) on conflict (id) do nothing;
insert into curriculum_topics values ('P1-social-and-citizenship-studies-t2-w8','ng-scheme-2025-preprimary-primary','P1','social-and-citizenship-studies',2,'8',8,'teaching',null,'Culture (Part 1)','["Understanding culture (the way of life of people)", "Nigerian culture is rich and diverse", "Elements of culture: language, food, dressing, festivals, greetings", "Different ethnic groups in Nigeria: Hausa, Igbo, Yoruba, and others", "Learning about our own culture"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,657) on conflict (id) do nothing;
insert into curriculum_topics values ('P1-social-and-citizenship-studies-t2-w9','ng-scheme-2025-preprimary-primary','P1','social-and-citizenship-studies',2,'9',9,'teaching',null,'Culture (Part 2)','["Traditional dressing: wrapper, buba, iro, gele, caftan, agbada", "Nigerian foods: jollof rice, pounded yam, egusi soup, tuwo, akara, moi-moi", "Traditional greetings: prostrating (Yoruba boys), kneeling (Yoruba girls), handshakes", "Cultural festivals and celebrations in our community", "Preserving our culture"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,657) on conflict (id) do nothing;
insert into curriculum_topics values ('P1-social-and-citizenship-studies-t2-w10','ng-scheme-2025-preprimary-primary','P1','social-and-citizenship-studies',2,'10',10,'teaching',null,'Introduction to Nigeria','["Nigeria is our country (located in West Africa)", "Nigeria has 36 states and Federal Capital Territory (Abuja)", "Our national language: English", "Major ethnic groups: Hausa, Igbo, Yoruba (and over 250 others)", "Major religions: Christianity, Islam, Traditional religions", "Nigeria''s motto: \"Unity and Faith, Peace and Progress\"", "Identifying our own state and local government"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,657) on conflict (id) do nothing;
