insert into curriculum_topics values ('P1-social-and-citizenship-studies-t3-w1','ng-scheme-2025-preprimary-primary','P1','social-and-citizenship-studies',3,'1',1,'teaching',null,'Attitudes and Values','["Understanding attitudes (how we think and feel about things)  Understanding values (what we believe is important)  Good attitudes: positive thinking, cheerfulness, willingness to help  Bad attitudes: complaining, laziness, selfishness  Nigerian core values: honesty, hard work, respect, integrity, patriotism"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,658) on conflict (id) do nothing;
insert into curriculum_topics values ('P1-social-and-citizenship-studies-t3-w2','ng-scheme-2025-preprimary-primary','P1','social-and-citizenship-studies',3,'2',2,'teaching',null,'Finding Help in Danger (Part 1)','["Understanding danger (situations that can harm us)  Types of danger: fire, accidents, getting lost, strangers, bad weather  Emergency situations: accidents, illness, natural disasters  People who can help: parents, teachers, police, doctors, firefighters  Importance of staying calm in dangerous situations"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,658) on conflict (id) do nothing;
insert into curriculum_topics values ('P1-social-and-citizenship-studies-t3-w3','ng-scheme-2025-preprimary-primary','P1','social-and-citizenship-studies',3,'3',3,'teaching',null,'Finding Help in Danger (Part 2)','["Emergency numbers in Nigeria: 112 (emergency), 767 (police in Lagos), 199 (fire service)  What information to give: name, location, type of emergency  Trusted adults to run to for help  Safety rules: don''t talk to strangers, don''t follow strangers, don''t accept gifts from strangers  Knowing your parents'' phone numbers and home address  \"Stranger Danger\" awareness"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,658) on conflict (id) do nothing;
insert into curriculum_topics values ('P1-social-and-citizenship-studies-t3-w4','ng-scheme-2025-preprimary-primary','P1','social-and-citizenship-studies',3,'4',4,'teaching',null,'Secure Environment (Part 1)','["Understanding a secure environment (a place where we are safe)  What makes a place secure: locks on doors, fences, lights, security guards  Feeling safe at home, school, and community  Dangers in our environment: open wells, busy roads, sharp objects, fire  How to stay safe: following rules, staying alert, reporting dangers"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,658) on conflict (id) do nothing;
insert into curriculum_topics values ('P1-social-and-citizenship-studies-t3-w5','ng-scheme-2025-preprimary-primary','P1','social-and-citizenship-studies',3,'5',5,'midterm_assessment',null,'Mid-term Examination','[" Assessment of Weeks 1-4"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,659) on conflict (id) do nothing;
insert into curriculum_topics values ('P1-social-and-citizenship-studies-t3-w6','ng-scheme-2025-preprimary-primary','P1','social-and-citizenship-studies',3,'6',6,'midterm_break',null,'Mid-term Break','[" Holiday/Rest"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,659) on conflict (id) do nothing;
insert into curriculum_topics values ('P1-social-and-citizenship-studies-t3-w7','ng-scheme-2025-preprimary-primary','P1','social-and-citizenship-studies',3,'7',7,'teaching',null,'Secure Environment (Part 2) & Climate Change and the Environment','["Keeping our environment clean and safe: proper waste disposal, not littering  Reporting broken or dangerous things to adults  Understanding weather and climate (sun, rain, wind, hot, cold)  Climate change (simple introduction): changes in weather patterns  Effects of climate change: too much heat, floods, droughts  Our role: planting trees, not wasting water, keeping environment clean"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,659) on conflict (id) do nothing;
insert into curriculum_topics values ('P1-social-and-citizenship-studies-t3-w8','ng-scheme-2025-preprimary-primary','P1','social-and-citizenship-studies',3,'8',8,'teaching',null,'Local Wildlife and Conservation','["Understanding wildlife (animals living in nature)  Nigerian animals: monkeys, antelopes, birds, lizards, snakes, butterflies  Where animals live: forests, rivers, grasslands  Why we should protect animals: they are part of nature, some are endangered  Conservation means protecting nature  Not harming animals, not destroying their homes  Visiting zoos to learn about animals"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,659) on conflict (id) do nothing;
insert into curriculum_topics values ('P1-social-and-citizenship-studies-t3-w9','ng-scheme-2025-preprimary-primary','P1','social-and-citizenship-studies',3,'9',9,'teaching',null,'Money (Part 1)','["Understanding money (what we use to buy things)  Nigerian currency: Naira (₦)  Coins: ₦1, ₦2 (if still in circulation)  Notes: ₦5, ₦10, ₦20, ₦50, ₦100, ₦200, ₦500, ₦1000  Identifying different denominations  Money has value - we work to earn money"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,659) on conflict (id) do nothing;
insert into curriculum_topics values ('P1-social-and-citizenship-studies-t3-w10','ng-scheme-2025-preprimary-primary','P1','social-and-citizenship-studies',3,'10',10,'teaching',null,'Money (Part 2)','["Uses of money: buying food, clothes, toys, paying for school, transportation  Earning money: parents work to earn money  Spending wisely: buying what we need, not wasting money  Saving money: keeping money for future use (piggy bank, savings box)  Not stealing money - honesty with money  Simple buying and selling activities (role-play)  Appreciating what parents buy with money"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,659) on conflict (id) do nothing;
