insert into curriculum_topics values ('P2-basic-science-t1-w1','ng-scheme-2025-preprimary-primary','P2','basic-science',1,'1',1,'teaching',null,'The Senses (Part 1): Sense of Sight','["Understanding our five senses", "The sense of sight: using our eyes", "Parts of the eye: eyelids, eyelashes, eyeball, pupil", "What we can see: colors, shapes, sizes, people, animals, objects", "Taking care of our eyes: washing face, not rubbing with dirty hands, enough light when reading", "Things that can harm our eyes: dust, sharp objects, too much sunlight", "Activity: Identifying objects by sight"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,680) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-basic-science-t1-w2','ng-scheme-2025-preprimary-primary','P2','basic-science',1,'2',2,'teaching',null,'The Senses (Part 2): Sense of Hearing and Touch','["Sense of hearing: using our ears", "Sounds we hear: loud, soft, pleasant, unpleasant", "Taking care of our ears: cleaning gently, avoiding loud sounds, not putting objects in ears", "Sense of touch: using our skin", "What we feel: hot, cold, soft, hard, rough, smooth, wet, dry", "Activity: Touch box - identifying objects by touch", "Matching sounds to objects"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,680) on conflict (id) do nothing;
