insert into curriculum_topics values ('P2-basic-science-t1-w4','ng-scheme-2025-preprimary-primary','P2','basic-science',1,'4',4,'teaching',null,'Soil Types (Part 1)','["Understanding what soil is: ground we walk on, where plants grow", "Where we find soil: gardens, farms, roads, forests", "Uses of soil: growing plants, making pots, building houses (mud)", "Types of soil: sandy soil, clay soil, loamy soil", "Sandy soil: rough, does not hold water well, feels grainy", "Observing and touching different soil types", "Activity: Collecting soil samples from different places"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,680) on conflict (id) do nothing;
