insert into curriculum_topics values ('P2-basic-science-t1-w7','ng-scheme-2025-preprimary-primary','P2','basic-science',1,'7',7,'teaching',null,'Soil Types (Part 2)','["Clay soil: smooth, sticky when wet, holds water well, cracks when dry", "Making things with clay soil: pots, bricks", "Loamy soil: mixture of sand and clay, best for growing plants, dark colored", "Comparing the three soil types: color, texture, water holding", "Which soil is best for farming: loamy soil", "Activity: Simple experiment - pouring water through different soils", "Drawing and coloring different soil types"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,681) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-basic-science-t1-w8','ng-scheme-2025-preprimary-primary','P2','basic-science',1,'8',8,'teaching',null,'Air (Part 1)','["Understanding air: all around us, we cannot see it but we can feel it", "How we know air exists: we breathe it, we feel wind, balloons inflate", "Air is important: we need it to breathe and live", "Things that need air: people, animals, plants", "Feeling air: waving hand, fanning, blowing", "Moving air is called wind", "Activity: Blowing balloons, making paper fans"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,681) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-basic-science-t1-w9','ng-scheme-2025-preprimary-primary','P2','basic-science',1,'9',9,'teaching',null,'Air (Part 2)','["Properties of air: has no color (transparent), has no smell, has no taste", "Air has weight: can be felt when moving", "Air occupies space: fills balloons, bubbles in water", "Uses of air: breathing, flying kites, drying clothes, winnowing grains", "Wind helps: moving windmills, sailing boats, spreading seeds", "Clean air vs. dirty air (smoke, dust)", "Activity: Observing bubbles in water, flying light objects with air"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,681) on conflict (id) do nothing;
