insert into curriculum_topics values ('P2-basic-science-t2-w1','ng-scheme-2025-preprimary-primary','P2','basic-science',2,'1',1,'teaching',null,'Water (Part 2)','["States of water: liquid (water we drink), solid (ice), gas (steam from boiling water)", "Water becomes ice when very cold (in freezer)", "Ice becomes water when warm (melting)", "Water becomes steam when boiled (evaporation - simple concept)", "Water cycle (very simple): rain falls, forms rivers, sun dries water, rain falls again", "Activity: Observing ice melting, watching steam from hot water (teacher demonstration)"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,683) on conflict (id) do nothing;
