insert into curriculum_topics values ('P2-basic-science-t2-w3','ng-scheme-2025-preprimary-primary','P2','basic-science',2,'3',3,'teaching',null,'Colours (Part 2)','["Secondary colors: green, orange, purple (made by mixing primary colors)", "Mixing colors: - Red + Yellow = Orange - Blue + Yellow = Green - Red + Blue = Purple", "Other colors: black, white, brown, pink, grey", "Colors in nature: rainbow colors", "Activity: Mixing paint/water colors to make new colors"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,683) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-basic-science-t2-w4','ng-scheme-2025-preprimary-primary','P2','basic-science',2,'4',4,'teaching',null,'Plants (Part 1): Parts of a Plant','["Understanding plants: living things that grow from soil", "Major parts of a plant: -Roots: under the ground, hold plant in soil, take in water - Stem: above ground, holds plant upright, carries water to leaves - Leaves: green parts, make food for plant -Flowers: colorful parts, some plants have them - Fruits: some plants have fruits with seeds inside", "Activity: Observing real plants, drawing and labeling plant parts"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,683) on conflict (id) do nothing;
