insert into curriculum_topics values ('P2-basic-science-t2-w7','ng-scheme-2025-preprimary-primary','P2','basic-science',2,'7',7,'teaching',null,'Plants (Part 2): Types and Uses of Plants','["Types of plants: trees (big, tall, woody stem), shrubs (smaller than trees), herbs (small, soft stem)", "Examples: mango tree, hibiscus shrub, tomato plant", "Uses of plants: - Food: fruits, vegetables, grains - Shelter: wood for building houses - Clothing: cotton for clothes - Medicine: herbs for treating sickness - Oxygen: plants give us fresh air to breathe", "Activity: Plant walk - identifying plants in school compound"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,684) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-basic-science-t2-w8','ng-scheme-2025-preprimary-primary','P2','basic-science',2,'8',8,'teaching',null,'Plants (Part 3): How Plants Grow','["What plants need to grow: soil, water, air, sunlight", "Stages of plant growth: seed → young plant (seedling) → adult plant", "Seeds come from fruits and flowers", "Caring for plants: watering, removing weeds, protecting from animals", "Activity: Planting seeds in pots (beans or maize), observing growth daily"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,684) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-basic-science-t2-w9','ng-scheme-2025-preprimary-primary','P2','basic-science',2,'9',9,'teaching',null,'Animals (Part 1): Types of Animals','["Understanding animals: living things that can move from place to place", "Animals around us: pets, farm animals, wild animals, insects, birds, fish", "Domestic animals (pets): dog, cat, rabbit, parrot", "Farm animals: goat, sheep, cow, chicken, duck, pig", "Wild animals: lion, elephant, monkey, snake, crocodile", "Activity: Sorting animal pictures by groups, animal sounds game"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,684) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-basic-science-t2-w10','ng-scheme-2025-preprimary-primary','P2','basic-science',2,'10',10,'teaching',null,'Animals (Part 2): Body Parts and Uses of Animals','["Body parts of animals: head, eyes, ears, legs, tail, wings (for birds)", "Different animals have different body parts: fish have fins, birds have wings, snakes have no legs", "Uses of animals: - Food: meat, milk, eggs - Work: donkeys carry loads, oxen plow farms - Protection: dogs guard homes -Clothing: leather from cow skin, wool from sheep", "Caring for animals: feeding, giving water, shelter, treating when sick", "Activity: Matching animals to their uses, drawing favorite animal"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,684) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-basic-science-t2-w11','ng-scheme-2025-preprimary-primary','P2','basic-science',2,'11',11,'revision',null,'Revision','["Review: Water states, colors, plants, animals"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,685) on conflict (id) do nothing;
