insert into curriculum_topics values ('P2-basic-science-t3-w1','ng-scheme-2025-preprimary-primary','P2','basic-science',3,'1',1,'teaching',null,'Clay (Part 1): What is Clay?','["Understanding clay: special type of soil that is sticky when wet", "Where clay is found: near rivers, in some farms, clay pits", "Properties of clay: - Soft and moldable when wet - Can be shaped into different forms - Becomes hard when dry - Smooth texture", "Difference between clay and other soils", "Activity: Touching and feeling wet clay, observing dry clay"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,686) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-basic-science-t3-w2','ng-scheme-2025-preprimary-primary','P2','basic-science',3,'2',2,'teaching',null,'Clay (Part 2): Uses of Clay','["What we make with clay: - Pots for cooking and storing water - Plates and bowls for serving food - Bricks for building houses - Tiles for floors and walls - Decorative items: vases, sculptures - Children''s toys", "People who work with clay: potters", "Traditional pottery in Nigeria: different ethnic groups'' pottery styles", "Activity: Visiting a potter (if possible) or watching video of pottery making"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,686) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-basic-science-t3-w3','ng-scheme-2025-preprimary-primary','P2','basic-science',3,'3',3,'teaching',null,'Clay (Part 3): Working with Clay','["How to prepare clay for molding: adding water, kneading", "Simple clay modeling techniques: - Rolling: making ropes and balls - Pinching: making small pots - Flattening: making flat shapes - Joining pieces together", "Drying clay objects: leaving in sun or shade", "Safety with clay: washing hands before and after, not eating clay", "Activity: Simple clay modeling - making balls, ropes, simple pots, animals"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,686) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-basic-science-t3-w4','ng-scheme-2025-preprimary-primary','P2','basic-science',3,'4',4,'teaching',null,'Clay (Part 4): Clay Art and Projects','["Decorating clay objects: making patterns, adding textures", "Painting dried clay objects", "Creating clay models: fruits, animals, simple shapes", "Appreciating traditional Nigerian pottery", "Caring for clay objects: handling gently, keeping dry", "Activity: Creating clay art project (individual or group), decorating clay objects"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,686) on conflict (id) do nothing;
