insert into curriculum_topics values ('P2-basic-science-t3-w7','ng-scheme-2025-preprimary-primary','P2','basic-science',3,'7',7,'teaching',null,'Forms of Energy: Sound (Part 1)','["Understanding energy: what makes things work, move, or change", "Introduction to sound: what we hear with our ears", "How sound is made: by vibrations (things shaking/moving quickly)", "Sources of sound: - Our voice: vocal cords vibrate - Musical instruments: drums, bells, whistles - Animals: dogs bark, birds sing, cats meow -Things around us: doors closing, car engines, rain", "Activity: Making sounds with our voices, identifying sounds"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,687) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-basic-science-t3-w8','ng-scheme-2025-preprimary-primary','P2','basic-science',3,'8',8,'teaching',null,'Forms of Energy: Sound (Part 2)','["Types of sounds: -Loud sounds: drum, thunder, car horn, shouting - Soft/quiet sounds: whisper, breeze, tiptoe - Pleasant sounds: music, singing, birds - Unpleasant sounds: noise, screaming, grinding", "High and low sounds (pitch): bird singing (high), drum beating (low)", "Fast and slow sounds", "Activity: Creating loud and soft sounds, identifying pleasant and unpleasant sounds"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,687) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-basic-science-t3-w9','ng-scheme-2025-preprimary-primary','P2','basic-science',3,'9',9,'teaching',null,'Forms of Energy: Sound (Part 3)','["How sound travels: through air, can travel through water and solid objects", "Sound travels from source to our ears", "Sounds can be near (close) or far (distant)", "Echo: hearing sound again (like in empty room or mountain)", "Uses of sound: -Communication: talking, telephone, school bell - Warning: alarm, siren, car horn - Entertainment: music, songs, stories", "Activity: Sound experiments - sounds through different materials"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,687) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-basic-science-t3-w10','ng-scheme-2025-preprimary-primary','P2','basic-science',3,'10',10,'teaching',null,'Forms of Energy: Sound (Part 4)','["Musical Instruments and Sound Safety", "Making musical instruments: - Shakers: containers with beans/stones - Drums: containers with stretched material - Bells: metal objects that ring - Whistles: blowing instruments", "Traditional Nigerian instruments: drums, gong, shekere, flute", "Sound safety: - Very loud sounds can hurt our ears - Don''t shout in people''s ears - Cover ears when near very loud sounds", "Activity: Making simple musical instruments from recycled materials, class orchestra"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,687) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-basic-science-t3-w11','ng-scheme-2025-preprimary-primary','P2','basic-science',3,'11',11,'revision',null,'Revision','["Review: Clay (properties, uses, modeling), Sound (sources, types, uses, safety)"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,688) on conflict (id) do nothing;
