insert into curriculum_topics values ('P2-physical-and-health-education-t1-w1','ng-scheme-2025-preprimary-primary','P2','physical-and-health-education',1,'1',1,'teaching',null,'Moving Our Body Parts (Part 1): Head and Upper Body','["Identifying body parts: head, neck, shoulders, arms, hands", "Moving the head: nodding (yes), shaking (no), turning left and right, up and down", "Moving shoulders: shrugging up and down, rolling forward and backward", "Moving arms: swinging, stretching up, sideways, circling", "Moving hands: waving, clapping, opening and closing fists", "Simple coordination: head and arm movements together", "Activity: \"Simon Says\" with upper body movements"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,689) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-physical-and-health-education-t1-w2','ng-scheme-2025-preprimary-primary','P2','physical-and-health-education',1,'2',2,'teaching',null,'Moving Our Body Parts (Part 2): Lower Body','["Identifying lower body parts: waist, hips, legs, knees, feet, toes", "Bending at the waist: forward, sideways, backward (carefully)", "Moving hips: side to side, circular motions", "Moving legs: lifting knees, kicking gently, stepping", "Moving feet: tiptoeing, stamping, standing on one foot", "Moving toes: wiggling, curling", "Balance activities: standing on one leg, walking on a line", "Activity: Follow-the-leader movement game"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,689) on conflict (id) do nothing;
insert into curriculum_topics values ('P2-physical-and-health-education-t1-w3','ng-scheme-2025-preprimary-primary','P2','physical-and-health-education',1,'3',3,'teaching',null,'Moving Our Body Parts (Part 3): Whole Body Movements','["Combining upper and lower body movements", "Basic locomotor movements: - Walking: forward, backward, sideways - Running: in place, short distances -Jumping: two feet together, hopping on one foot - Skipping: combining step and hop - Galloping: like a horse", "Stretching exercises: reaching high, bending low, stretching wide", "Activity: Movement stations, obstacle course"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,689) on conflict (id) do nothing;
